const PZ_STANDARD_FOOTER_CSS="body>footer.pz-standard-footer{display:block;position:static;float:none;width:100%;max-width:none;margin:0;padding:26px max(24px,env(safe-area-inset-right,0px)) 24px max(24px,env(safe-area-inset-left,0px));border:0;border-top:1px solid #e2e4e8;background:#fff;color:#4b5563;font:13px/1.5 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;text-align:left;box-sizing:border-box}body>footer.pz-standard-footer>.pz-footer-inner{width:100%;max-width:1200px;margin:0 auto;padding:0;display:grid;grid-template-columns:minmax(140px,1.25fr) repeat(3,minmax(0,1fr));gap:18px 24px;align-items:start;justify-content:initial}body>footer.pz-standard-footer .pz-footer-brand{display:block;min-width:0}body>footer.pz-standard-footer .pz-footer-brand a{display:inline-flex;font-size:19px;font-weight:780;letter-spacing:-.035em;color:#191919}body>footer.pz-standard-footer .pz-footer-tagline{display:block;margin:4px 0 0;color:#656b74;font-size:12px;font-weight:400}body>footer.pz-standard-footer .pz-footer-group{display:flex;flex-direction:column;align-items:flex-start;min-width:0;gap:2px}body>footer.pz-standard-footer .pz-footer-label{font-size:12px;font-weight:750;color:#191919;margin:0 0 4px}body>footer.pz-standard-footer a,body>footer.pz-standard-footer button.pz-footer-link{display:inline-flex;align-items:center;min-height:28px;max-width:100%;padding:0;color:#4b5563;text-decoration:none;text-align:left;font:inherit;white-space:normal;overflow-wrap:anywhere;border:0;background:none;box-shadow:none;border-radius:0;cursor:pointer}body>footer.pz-standard-footer a:hover,body>footer.pz-standard-footer button.pz-footer-link:hover{text-decoration:underline;text-underline-offset:3px;color:#191919}body>footer.pz-standard-footer a:focus-visible,body>footer.pz-standard-footer button.pz-footer-link:focus-visible{outline:2px solid #52657e;outline-offset:3px;border-radius:3px}@media(max-width:760px){body>footer.pz-standard-footer{padding:20px max(16px,env(safe-area-inset-right,0px)) 20px max(16px,env(safe-area-inset-left,0px))}body>footer.pz-standard-footer>.pz-footer-inner{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px}body>footer.pz-standard-footer a,body>footer.pz-standard-footer button.pz-footer-link{min-height:44px}}@media(max-width:760px),(hover:none) and (pointer:coarse) and (max-width:1024px){body:has(>.pz-mobile-nav)>main{padding-bottom:24px}body:has(>.pz-mobile-nav)>footer.pz-standard-footer{padding-bottom:calc(100px + env(safe-area-inset-bottom,0px))}}";
function pzStandardFooter(analytics=false){return "<footer class=\"pz-standard-footer\" aria-label=\"Project Zero footer\"><div class=\"pz-footer-inner\"><div class=\"pz-footer-brand\"><a href=\"https://www.projectzero.work/?home=1\" aria-label=\"Project Zero public home\">Project Zero</a><span class=\"pz-footer-tagline\">From idea to operating business.</span></div><div class=\"pz-footer-group\" role=\"navigation\" aria-label=\"Explore Project Zero\"><span class=\"pz-footer-label\">Explore</span><a href=\"https://www.projectzero.work/?home=1\">Home</a><a href=\"https://guides.projectzero.work/\">Platform guides</a><a href=\"https://guides.projectzero.work/how-to\">How-to guides</a><a href=\"https://www.projectzero.work/demo\">Interactive demo</a></div><div class=\"pz-footer-group\" role=\"navigation\" aria-label=\"Workspace and account\"><span class=\"pz-footer-label\">Workspace</span><a href=\"https://dash.projectzero.work/\">Dashboard</a><a href=\"https://account.projectzero.work/\">Account</a><a href=\"mailto:support@projectzero.work\">Support</a></div><div class=\"pz-footer-group\" role=\"navigation\" aria-label=\"Legal and resources\"><span class=\"pz-footer-label\">Resources &amp; policies</span><a href=\"https://www.projectzero.work/privacy\">Privacy Policy</a><a href=\"https://www.projectzero.work/terms\">Terms of Service</a><a href=\"https://guides.projectzero.work/methodology\">Editorial policy &amp; disclosures</a><a href=\"https://www.projectzero.work/sitemap.xml\">Sitemap</a>"+(analytics?"<button id=\"pz-analytics-settings\" class=\"pz-footer-link pz-analytics-settings\" type=\"button\">Analytics preferences</button>":'')+'</div></div></footer>'}
