const CALCULATOR="(()=>{'use strict';const root=document.querySelector('[data-calculator]');if(!root)return;const money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});const get=k=>{const el=root.querySelector('[name=\"'+k+'\"]');const v=Number(el?.value);return Number.isFinite(v)?Math.max(0,Math.min(v,Number(el.max)||1e9)):0};const out=(k,v)=>{const e=root.querySelector('[data-result=\"'+k+'\"]');if(e)e.textContent=v};function calc(){if(root.dataset.calculator==='hosting'){const fixed=get('hosting')+get('database')+get('email')+get('analytics')+get('other')+get('domain')/12;const variable=get('usage')*get('rate');const subtotal=fixed+variable,total=subtotal*(1+get('reserve')/100),budget=get('budget');out('fixed',money(fixed));out('variable',money(variable));out('total',money(total));out('annual',money(total*12));out('budget',money(Math.abs(budget-total))+(total>budget?' over budget':' remaining'));}else{const price=get('price'),count=Math.floor(get('count')),gross=price*count;const fa=count*(price*get('percent_a')/100+get('fixed_a'))+get('monthly_a'),fb=count*(price*get('percent_b')/100+get('fixed_b'))+get('monthly_b');out('gross',money(gross));out('fee_a',money(fa));out('fee_b',money(fb));out('net_a',money(gross-fa));out('net_b',money(gross-fb));out('difference',money(Math.abs(fa-fb))+(Math.abs(fa-fb)<0.005?' equal costs':fa<fb?' lower with A':' lower with B'));}}root.addEventListener('input',calc);root.addEventListener('change',calc);calc();root.querySelector('[data-reset]')?.addEventListener('click',()=>{root.querySelectorAll('input').forEach(el=>el.value=el.defaultValue);calc()});})();";
const ANALYTICS_SCRIPT="(()=>{'use strict';const banner=document.getElementById('pz-analytics-choice'),settings=document.getElementById('pz-analytics-settings');if(!banner||!settings)return;const key='pz-analytics-choice-v1';const blocked=navigator.doNotTrack==='1'||navigator.globalPrivacyControl===true;let loaded=false,choice='';try{choice=localStorage.getItem(key)||''}catch{}function enable(){if(blocked||loaded)return;loaded=true;const script=document.createElement('script');script.src='https://siteapt.app/tracker.js';script.dataset.site=banner.dataset.site;script.defer=true;document.head.append(script);let lastCalc=false;document.querySelector('[data-calculator]')?.addEventListener('input',()=>{if(!lastCalc){lastCalc=true;event('calculator_used')}});document.addEventListener('click',e=>{const link=e.target.closest?.('a[href]');if(!link)return;const u=new URL(link.href,location.href);if(link.relList?.contains('sponsored'))event('affiliate_link_click');else if(u.hostname==='dash.projectzero.work')event('workspace_signin_click');else if(u.hostname==='guides.projectzero.work'&&location.hostname!==u.hostname)event('guides_click');else if(u.origin!==location.origin&&u.protocol==='https:'&&u.hostname!=='siteapt.app')event('external_link_click')})}function event(name){if(loaded&&choice==='yes')dispatchEvent(new CustomEvent('statatlas:conversion',{detail:{name,path:location.pathname}}))}function select(value){choice=value;try{localStorage.setItem(key,value)}catch{}banner.hidden=true;if(value==='yes')enable();else if(loaded){try{for(const prefix of ['sa-v-','sa-s-','sa-t-'])sessionStorage.removeItem(prefix+banner.dataset.site)}catch{}location.reload()}}banner.querySelector('[data-allow]').addEventListener('click',()=>select('yes'));banner.querySelector('[data-deny]').addEventListener('click',()=>select('no'));settings.addEventListener('click',()=>{if(blocked){banner.hidden=false;banner.querySelector('[data-allow]').hidden=true;banner.querySelector('p').textContent='Your browser has requested that analytics be disabled.';return}banner.hidden=!banner.hidden});if(blocked){banner.hidden=true;return}if(choice==='yes'){banner.hidden=true;enable()}else banner.hidden=choice==='no'})();";
const FILTER="(()=>{const q=document.getElementById('provider-search');if(!q)return;const cards=[...document.querySelectorAll('[data-provider]')],out=document.getElementById('search-result');q.addEventListener('input',()=>{const v=q.value.trim().toLowerCase();let n=0;cards.forEach(c=>{const hit=c.textContent.toLowerCase().includes(v);c.hidden=!hit;if(hit)n++});out.textContent=n+' matching providers'})})();";
