function pricing(p){const referral=approvedReferral(p);return '<div class="pricing"><h2>Pricing and billing</h2><p class="price">'+esc(fresh(p)?p.pricing:'Current rates require verification. Check the official pricing page before deciding.')+'</p><p class="status '+(fresh(p)?'checked':'')+'">'+esc(dateText(p))+'</p>'+(fresh(p)?'':'<p class="muted">Previous summary (not confirmed current): '+esc(p.pricing)+'</p>')+(referral?'<p class="notice">'+esc(referral.disclosure)+'</p>':'')+'<div class="buttons"><a class="button" href="'+esc(url(p.pricing_url)||url(p.url))+'" rel="noopener noreferrer" target="_blank">Official pricing ↗</a><a class="button secondary" href="'+esc(url(p.url))+'" rel="noopener noreferrer" target="_blank">Visit '+esc(p.name)+' ↗</a>'+(referral?'<a class="button" href="'+esc(referral.href)+'" rel="sponsored">Start with '+esc(p.name)+' (affiliate link) ↗</a>':'')+'</div><small>Prices shown are US examples unless specified. Verify usage, taxes, renewal, commercial eligibility and checkout terms.</small></div>'}
let memo=null,loaded=0;
async function load(env){if(memo&&Date.now()-loaded<300000)return memo;const obj=await env.GUIDES.get('catalog/v1.json');if(!obj)throw Error('catalog unavailable');const d=await obj.json();if(d.schema!==1||!Array.isArray(d.providers)||d.providers.length<1||d.providers.length>100)throw Error('invalid catalog');const ps=d.providers.filter(p=>typeof p.name==='string'&&CATEGORIES[p.category]&&url(p.url)&&url(p.pricing_url)&&['pricing','benefits','best_for','tradeoffs'].every(k=>typeof p[k]==='string'&&p[k].length<=3000));if(ps.length!==d.providers.length||new Set(ps.map(p=>slug(p.name))).size!==ps.length)throw Error('invalid provider records');memo=ps;loaded=Date.now();return ps}
function sitemap(ps){const loc=(p,date)=>'<url><loc>'+esc(BASE+p)+'</loc>'+(validDate(date)?'<lastmod>'+date+'</lastmod>':'')+'</url>';return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+['/','/privacy','/platforms','/compare','/methodology','/tools','/tools/hosting-cost-calculator','/tools/payment-fee-calculator','/tools/website-budget-worksheet','/setups',...TUTORIALS.map(t=>'/setups/'+t.slug),'/how-to',...HOWTOS.map(howPath),...Object.keys(CATEGORIES).map(cpath),...COMPARES.map(c=>'/compare/'+c.slug)].map(p=>loc(p)).join('')+ps.map(p=>loc(ppath(p),p.verified_at)).join('')+'</urlset>'}
function listing(ps){return '<div class="filter"><label for="provider-search">Search platforms</label><input type="search" id="provider-search" placeholder="Name or use case" maxlength="100" autocomplete="off"></div><p class="muted" id="search-result" aria-live="polite">'+ps.length+' provider guides</p><div class="grid">'+ps.map(card).join('')+'</div>'}

function comparisonProviders(list){return '<div class="compare-provider-grid">'+list.map(p=>'<section class="compare-provider"><div class="compare-provider-head"><span class="mark">'+icon(p.category)+'</span><h3><a href="'+ppath(p)+'">'+esc(p.name)+'</a></h3></div><div class="compare-price"><span class="compare-label">Pricing</span><p>'+esc(fresh(p)?p.pricing:'Check official current pricing.')+'</p><small class="status '+(fresh(p)?'checked':'')+'">'+esc(dateText(p))+'</small></div><div class="compare-facts"><div><span class="compare-label">Best for</span><p>'+esc(p.best_for)+'</p></div><div><span class="compare-label">Watch for</span><p>'+esc(p.tradeoffs)+'</p></div></div><div class="compare-provider-actions"><a href="'+ppath(p)+'" class="button secondary">Full guide →</a><a href="'+esc(url(p.pricing_url)||url(p.url))+'" target="_blank" rel="noopener noreferrer" class="compare-source">Official pricing ↗</a></div></section>').join('')+'</div>'}


const TUTORIALS=[{"slug":"launch-a-business-website","title":"Launch a small business website","desc":"A practical static website setup with source control, hosting, domain and analytics.","type":"hosting","budget":"Illustrative $15/year domain + $0/month hosting within eligible free limits = $1.25/month equivalent. Domain cost is an assumption, not a provider quote.","providers":["GitHub","Cloudflare","Netlify","Cloudflare Registrar","SiteAPT"],"steps":[["Define the first release","Pick one primary customer action, such as contacting you. Write the homepage, contact, product/service and privacy content before adding infrastructure."],["Create and deploy source","Use a private or public repository appropriate to your content; keep secrets out of Git. Choose static hosting with commercial eligibility and deploy a preview from the default branch."],["Connect the domain","Verify ownership, DNS records, HTTPS and both www and apex behavior. Preserve existing mail DNS. Use one canonical hostname and redirect duplicates."],["Measure and verify","Add analytics only under an appropriate privacy/consent approach. Check mobile layout, accessibility, broken links, contact delivery and sitemap before publishing."]],"tests":["Homepage and contact flow work on a phone.","Canonical hostname redirects and TLS work.","No credentials in source; restore a previous release.","Check actual renewal and usage costs."]},{"slug":"build-a-low-cost-saas","title":"Build a low-cost SaaS application","desc":"Plan a small paid web app with database, authentication, checkout and operating budget.","type":"database","budget":"Example: $5 hosting + $0 database/email within verified allowances + $1.25 domain equivalent + $3 reserve = $9.25/month before transaction fees. A managed PostgreSQL or identity plan could cost substantially more.","providers":["Cloudflare","Cloudflare D1","Supabase","Clerk","Stripe","Resend"],"steps":[["Validate the paid use case","Choose a single problem, a target customer, a first price and one workflow customers can finish. Test willingness to pay before expanding the feature list."],["Select the runtime and data model","Choose edge SQLite-compatible storage or PostgreSQL based on queries and existing code. Add indexes, migrations, tenant keys and backups. Keep files separate from relational records."],["Build customer identity and billing","Enforce authorization on every workspace query. Test sign-in, logout and account recovery. Verify checkout in test mode, signed webhooks, duplicate events, subscription changes and entitlement removal."],["Deploy with limits","Use staging, scoped deployment credentials, monitoring and resource caps. Test a backup restore, cost alerts and rollback before accepting payment."]],"tests":["Two test tenants cannot access one another's data.","Successful, failed, canceled and refunded payments update access correctly.","Backup restoration and rollback are demonstrated.","Cost model includes payment fees and usage limits."]},{"slug":"start-an-online-store","title":"Set up an online store","desc":"Choose a storefront, fulfillment and payments with a per-order margin model.","type":"commerce","budget":"Illustrative $30 sale – $12 production – $5 shipping – $1.20 payment fee – $2 returns reserve = $9.80 contribution before storefront, taxes, ads and labor. Substitute actual supplier and processor rates.","providers":["Shopify","WooCommerce","Printify","Stripe","PayPal"],"steps":[["Choose products and validate margins","Calculate product, packaging, shipping, payment and expected returns costs per order. Check supplier quality with samples and disclose delivery estimates."],["Select storefront and fulfillment","Choose hosted commerce or self-managed WordPress by maintenance burden. Connect a fulfillment supplier only when required; verify variants, stock and order routing."],["Configure checkout and policies","Configure shipping zones, tax responsibilities, payment methods and clear refunds. Use test mode to exercise successful and failed checkouts without live charges."],["Verify delivery and operations","Test order confirmations, fulfillment status, support replies, cancellation and refund reconciliation. Monitor contribution margin rather than gross sales."]],"tests":["Test order reaches the correct fulfillment destination.","Shipping, taxes and refund terms are visible before payment.","A refund updates order and finance records.","Actual margin remains positive after fixed expenses."]},{"slug":"release-a-desktop-app","title":"Release a downloadable desktop app","desc":"A checklist for licensing, secure releases, signing and software updates.","type":"distribution","budget":"Model signing and publishing fees separately from download hosting and payment fees. Illustrative $49 one-time sale with a $2.95 fee leaves $46.05 before refunds, tax and support; verify the fee model.","providers":["GitHub Releases","Cloudflare R2","Apple Developer","Microsoft Partner Center","Lemon Squeezy"],"steps":[["Specify supported platforms","List supported OS versions and architectures. Set up reproducible builds, documented installation and test machines; don't promise unsupported hardware."],["Secure artifacts","Sign releases where required, publish checksums, keep private keys out of repositories, and use a predictable versioned update mechanism."],["Deliver entitlements","Choose a payment processor or merchant of record that accepts the product. Test license issuance, activation, device limits, offline behavior and refunds without live charging."],["Test real installation","Install a fresh build on each supported OS, test upgrades and uninstall, verify rollback and support documentation. Review store requirements if publishing through stores."]],"tests":["Install and update from a clean machine.","Invalid or refunded licenses are handled as documented.","Downloads and update manifests are authenticated.","Support and refund process is tested."]},{"slug":"launch-a-mobile-app","title":"Prepare an Android or iOS app for launch","desc":"Plan publishing accounts, testing, signing, privacy and optional backend services.","type":"distribution","budget":"Include store registration and renewal, signing, testing devices, backend usage and store commissions. Treat one-time fees as launch costs and annual fees as monthly equivalents.","providers":["Google Play Console","Apple Developer","Firebase","Sentry","GitHub Actions"],"steps":[["Choose the smallest supported release","Pick one or both platforms based on customer demand. Specify device and OS coverage, offline behavior and accessibility."],["Set up build and publishing ownership","Create or reuse the correct developer account only after approval. Protect signing keys, bundle identifiers, build pipeline and store access."],["Build privacy and entitlement flows","Request only necessary permissions. Review store payment rules for digital products and subscription restoration. Use a backend only when required."],["Test distribution","Use appropriate internal or closed testing tracks. Validate installation, updates, error recovery, privacy declarations and store review requirements."]],"tests":["Install on physical devices.","Permission denial and offline behavior work.","Store test purchases and restore work if applicable.","Privacy statements match actual data collection."]},{"slug":"deploy-an-api-or-self-hosted-service","title":"Deploy a small API or self-hosted service","desc":"Choose serverless or a VM with authentication, backups, monitoring and cost controls.","type":"hosting","budget":"Illustrative $4 VM + $2 backup allowance + $1.25 domain equivalent = $7.25/month before transfer and administration. A free-tier API may suit request-based workloads but not persistent processes.","providers":["Cloudflare","DigitalOcean","Render","Cloudflare R2","Backblaze B2","UptimeRobot"],"steps":[["Measure workload requirements","Estimate requests, memory, CPU time, persistent connections, disk and background processes. Select a runtime that supports them."],["Secure access","Use scoped credentials, HTTPS, authentication and rate limits. Restrict administrative endpoints and avoid exposing internal services or secrets in logs."],["Deploy and monitor","Create a repeatable release process with staging and rollback. Set health checks, error alerts and cost monitoring; account for transfer and storage."],["Prove recovery","Back up the correct data, test a restore, simulate a failed deployment and document incident ownership. Keep maintenance and dependency updates on a schedule."]],"tests":["Unauthorized requests fail closed.","Rate limits and timeouts work.","A restored backup works on a clean environment.","Resource estimates and alerts match actual usage."]}];


const PROVIDER_EDITORIAL={"Cloudflare":["Use Pages for a static brochure or frontend, Workers for request-driven application logic, and dedicated storage only where persistence is necessary. A static site can be much simpler than an edge API.","Connect a source repository and set the build command and output directory; check the generated preview before attaching your domain.","Test a request that reads and writes data, check logs and CPU usage, and keep a known-good deployment available for rollback.","A site that loads but cannot save data often has an absent environment binding or a production/preview configuration mismatch. Inspect both environments before changing DNS."],"Vercel":["A strong candidate for framework-driven frontends and server-rendered applications; a static HTML site may need less infrastructure. Check commercial plan eligibility before launch.","Import the repo, verify framework detection and build output, then configure environment variables separately for preview and production.","Visit a preview URL, exercise server-side routes, then connect the custom domain and verify redirects and certificate issuance.","If a build works locally but fails remotely, check runtime version, lockfile, required build variables and case-sensitive imports."],"Netlify":["Useful for static storefronts, documentation and marketing sites with Git-based deployment. Evaluate function limits separately if your site has dynamic logic.","Connect a repository, set the publishing directory and build command, then inspect deploy previews before merging.","Test direct visits to nested routes, form submissions if used, and a clean mobile load on the custom domain.","A blank page or missing assets can result from pointing the publish directory at source code instead of compiled output; single-page apps also need an appropriate routing fallback."],"DigitalOcean":["A Droplet is a virtual server: suitable for a long-running process, Docker service or application needing OS-level control. A static site rarely requires a VM.","Choose a region and size from measured RAM and CPU requirements. Use an SSH key, restricted administrative access and a non-root deployment user.","Install only required packages, configure a cloud firewall, expose HTTPS through a reverse proxy and set up backups. Restore a copy to another machine before launch.","If a service is unreachable, check its listening address, firewall, DNS and proxy logs in that order. Deleted compute and detached storage have different billing implications; audit resources."],"AWS":["Start with one service that directly solves your workload; a small application can become expensive when load balancers, NAT, logs and storage are added casually.","Create scoped roles under a protected account, choose a region, deploy a small staging workload and configure budget notifications.","Measure every resource attached to the workload, including logs, storage, requests and network transfer; practice removing a disposable stack.","Unexpected bills often come from resources that remain provisioned after the app is removed. Inspect billing by service and region before cleaning up."],"Render":["A managed service can suit APIs and background tasks when you want fewer server administration duties. Confirm whether the service sleeps or requires a persistent disk.","Connect the code, choose the service type, configure build and start commands, and supply environment secrets in the provider settings.","Set a health endpoint, test database connections from the deployed environment, and verify data survives a restart where persistence is expected.","If deployment repeatedly fails, compare build logs with startup logs and check whether the app binds to the port supplied by the hosting environment."],"Railway":["Good for experimenting with a multi-service stack where an API, database and background worker can live together. Resource-based charges need particular attention.","Create a project from the repository, add only necessary dependencies and configure references between services rather than hard-coding credentials.","Deploy a test environment, simulate traffic and inspect CPU/memory consumption; check what happens when the workload is idle.","Connection failures may mean the app is targeting the wrong internal hostname or port. Verify environment references and database availability before exposing a public endpoint."],"Hostinger":["Consider shared or managed web hosting for a simple content site; evaluate VPS separately when custom server software is essential.","Compare the renewal term, storage, backups and supported PHP/runtime versions before selecting a plan. Deploy a staging copy first.","Connect the domain only after checking pages, forms, updates and backups; retain control of the registrar and exportable site files.","If WordPress displays old content after a change, distinguish browser/CDN cache from the site's own cache. Check logs before disabling plugins."],"Cloudflare Registrar":["Most useful when you want domain registration and DNS managed in the same ecosystem. Evaluate how the domain can be transferred or managed if your hosting changes.","Check availability and the exact renewal price, enable account MFA and auto-renew where appropriate, then record authoritative nameservers.","Add the intended web records while preserving mail and verification records; test DNS answers and HTTPS from outside your account.","If a transfer stalls, verify the registrar lock, authorization process, eligibility and contact information without repeatedly changing nameservers."],"Namecheap":["Useful for separating registration from hosting. Compare renewal and transfer pricing instead of selecting solely on the first-year promotion.","Register under an owner-controlled account, protect recovery email and document the nameservers. Choose either registrar DNS or a third-party DNS provider.","Verify A, AAAA or CNAME records required by the host and maintain MX/TXT records if email already works.","If changes appear ineffective, check which nameservers are authoritative; editing a non-authoritative DNS panel has no effect."],"Porkbun":["Consider a registrar with straightforward domain management if your business already hosts elsewhere. Confirm extension-specific renewal conditions.","Choose the exact spelling and extension, inspect recurring costs, and protect account access before pointing the domain at your provider.","Verify apex and www resolution, HTTPS and mail delivery; store the DNS records and renewal date in an owner-accessible record.","A correct DNS entry does not guarantee an issued certificate. Follow the hosting provider's domain-validation process and allow DNS caches to expire."],"GoDaddy":["Consider the registrar service independently of bundled email, hosting or website-builder products. Itemize optional renewals before checkout.","Review the cart for term length and added services, enable MFA, then set DNS using the hosting provider's required targets.","Check the domain's renewal date and ownership, verify redirects and run a test message if existing mail is affected.","If a forwarding rule loops, distinguish domain forwarding from the application's redirect logic. Keep one canonical destination."],"Cloudflare D1":["Use relational SQLite-style data for small application records and queries where its runtime and limits match the workload.","Model tenant-scoped tables, add indexes matching filters, create a migration and bind a separate test database to your Worker.","Run realistic filtered queries and compare rows examined; test migration and restore procedures on disposable data before touching production.","A small result set can still require a large scan. Inspect query plans and add targeted indexes instead of increasing read usage blindly."],"Supabase":["Choose managed PostgreSQL when SQL, schemas and relational constraints are central; decide separately whether to use its authentication and storage.","Create a staging project, define migrations and row security policies, and use separate server and public-client credentials correctly.","Test two users with independent records and attempt cross-account reads and writes; export a test backup and restore it.","A working client query with an elevated key proves very little about authorization. Test with the same restricted identity a customer uses."],"Neon":["A useful option for PostgreSQL-based apps that need isolated database development workflows. Compare compute activity and storage requirements.","Create a separate development branch or database, use a connection string from secrets, then apply migrations via the same tool used in production.","Verify transaction behavior, connection pooling and representative query latency from the actual deployed application.","If connections time out under bursts, inspect pooling, transaction duration and app connection reuse rather than simply raising limits."],"Firebase":["Consider its integrated application ecosystem for client-heavy web or mobile projects. Choose the database model based on query patterns and document reads.","Create a test project and model the documents/collections around required queries. Define security rules before allowing client access.","Exercise denied reads, authenticated writes and offline behavior in a test setup; estimate document operations from actual screens.","If a list page becomes expensive, inspect repeated listeners and unnecessary document reads; unsubscribe from listeners when views close."],"Cloudflare R2":["Use object storage for uploads, downloads and static assets; do not treat object keys as a relational database or expose private files publicly.","Create a private bucket, add a least-privilege binding or credential, and define object keys that do not reveal personal information.","Upload and retrieve sample objects, verify content types, cache behavior and authorization, then test deletion and recovery policies.","When a download is forbidden, check access method, credentials and object key casing. Never make the entire bucket public just to resolve one permission error."],"Amazon S3":["A flexible object store for larger ecosystems and integrations, with region, storage class, access and transfer costs to evaluate.","Create a private bucket and a narrowly scoped role, enable appropriate encryption and define retention or lifecycle policies.","Test a temporary authorized download, expired access and deletion behavior. Estimate requests and retrieval fees for the chosen class.","For access denied errors, inspect role policy, bucket policy and encryption-key permissions; do not disable public access protections."],"Backblaze B2":["Consider object storage for archived backups and downloads, with restore and traffic behavior included in the cost estimate.","Create a private bucket and limited application key. Configure the backup client, upload a small known dataset and record its checksums.","Restore to a different location and compare file hashes; schedule retention and periodically test recovery.","Backup storage is not itself a disaster-recovery plan. If an upload fails, check quota, key scope and retry behavior without exposing the key."],"Supabase Storage":["Suitable when uploaded files belong to users already represented in your Supabase application. Database and bucket authorization must agree.","Create a private bucket, choose MIME type and size constraints, and define access policies that relate objects to user ownership.","Have two users attempt to fetch each other's uploads and verify signed links expire; test deletion of an account's associated objects.","If direct access works only with a service role, review storage policies; service credentials belong only on the server."],"Cloudflare Access":["Useful for staff-only dashboards or internal services. It is not a replacement for tenant permissions inside a customer application.","Configure an appropriate identity provider and a narrowly scoped application policy; start with a staging hostname.","Verify an authorized staff member enters and an unrelated account is denied, including direct access to backend endpoints.","If users loop through sign-in, check audience, policy or callback settings; do not open the production app to everyone as a workaround."],"Clerk":["Consider managed identity when polished sign-in and account components reduce development effort. Application authorization is still your responsibility.","Configure test and production instances separately, select identity methods, and store server keys outside browser code.","Validate sessions server-side, map users to workspace membership and test sign-out, expiry, deleted accounts and denied access.","A visible signed-in UI is not evidence that an API is protected. Verify each API route rejects unauthenticated and wrong-tenant requests."],"Auth0":["Useful when a centralized identity platform and standards-based integrations are needed. Model connection and organization requirements early.","Register a test application with exact callback and logout URLs. Use an appropriate OAuth flow and keep confidential credentials server-side.","Check issuer, audience, expiry and signature on server tokens; test account recovery and a denied user.","Callback mismatch errors usually involve exact scheme, host or path differences. Avoid wildcard callbacks in production."],"Supabase Auth":["Fit for an application using Supabase data and user identities, particularly when database row policies enforce ownership.","Choose login methods, configure approved redirect URLs and ensure user-facing emails lead to the correct environment.","Use session identity in row-level policies; test unauthenticated access, a second user and recovery or verification links.","If sign-in succeeds but rows are missing, inspect the user's session and policy predicate rather than bypassing row security."],"Firebase Authentication":["Consider when an app already uses Firebase and wants managed user identities across platforms.","Set up a separate test project, enable the desired sign-in methods and register the application's authorized domains or platform configuration.","Validate ID tokens on trusted servers and connect identity checks to database rules; test revoked or expired sessions.","A user ID stored by the client can be tampered with. Derive identity from a verified token rather than trusting a request body."],"Stripe":["Useful for custom checkout or subscriptions when you want control over pricing and entitlement workflows. Distinguish processor and merchant-of-record offerings.","Create products and prices in test mode, integrate hosted checkout or an approved payment component, and use an exact server-side price identifier.","Handle signed webhooks idempotently and test payment failure, duplicate event delivery, cancellation and refunds before granting real access.","A checkout success redirect is not proof of settled payment. Confirm authoritative event and account state on the server."],"Paddle":["Consider a merchant-of-record model for eligible digital products; verify your product and territory are covered rather than assuming all businesses qualify.","Use the provider's sandbox to create a product and checkout, then associate seller-side customer records with transaction data.","Test signed events, refunds, subscription changes and access removal; reconcile net payouts against your internal ledger.","If access remains after cancellation, inspect the subscription effective date and retry handling instead of relying only on frontend checkout state."],"Lemon Squeezy":["Consider a digital-product commerce platform when hosted sales and licensing features meet the delivery model. Check product eligibility and payout terms.","Create a test store/product and define variants, license expectations and delivery URLs. Keep real customer data out of staging.","Test purchase, license delivery, renewal or refund handling and webhook signatures; document support for activation failure.","A generated license is not enough: test invalid, expired or deactivated licenses against the exact version of your application."],"PayPal":["Consider offering PayPal when customers prefer its wallet or an additional payment option. Compare fees and settlement with your existing processor.","Configure a sandbox integration, define order totals on the server and capture only after appropriate approval.","Validate completed and failed transactions, duplicate captures, refunds and reconciliation without relying on the browser alone.","If a payment appears pending, look at its authoritative transaction status and avoid granting irreversible delivery prematurely."],"Resend":["Useful for transactional application emails such as confirmations and password resets, not necessarily for a full customer-support inbox.","Verify a sending domain with its required DNS records and store a scoped API key server-side; test to an address you control.","Send a confirmation and an error-path notification; record delivery events and handle bounces without exposing message content.","If messages land in spam, check authentication alignment, sender reputation and content before retrying repeatedly."],"Postmark":["Consider a transactional service for predictable operational messages with clear delivery diagnostics. Separate promotional traffic where appropriate.","Create a sender/domain, verify required DNS records and configure dedicated server credentials in test and production.","Test delivery events, hard bounces and complaint suppression; make confirmation messages short and useful.","If an address is suppressed, investigate the underlying bounce or complaint instead of automatically overriding suppression."],"SendGrid":["Useful when you need programmable outbound mail and can manage domain reputation and delivery monitoring.","Authenticate the sending domain and use a narrowly scoped mail key; configure templates and test without importing customer lists.","Test send failures and event processing, remove invalid addresses and avoid putting confidential user data in logging.","An accepted API request is not necessarily delivered mail. Inspect provider delivery events and the recipient's mail server response."],"Amazon SES":["Suitable for applications that can manage AWS identity, sending quotas and deliverability operations. Account setup and sending eligibility are separate concerns.","Choose the region, authenticate the domain and confirm sandbox or production permissions. Create a scoped sending identity.","Send to controlled addresses and process delivery or bounce notifications; monitor reputation before increasing volume.","If messages are rejected, check region-specific verification, sending access and quotas rather than rotating credentials blindly."],"Google Workspace":["Best considered for staff mailboxes and collaboration rather than high-volume application email.","Choose owner-controlled admin accounts, verify the domain and stage mail migration before changing MX records.","Create a test mailbox, test inbound/outbound delivery, configure MFA and document account recovery and offboarding.","If inbound works but outbound fails authentication checks, review SPF, DKIM and DMARC alignment; avoid multiple conflicting SPF records."],"Cloudflare Email Routing":["Good for forwarding incoming domain messages to an existing inbox; treat outbound sending as a separate requirement.","Verify the destination address and the required DNS records. Create an explicit address rule for support or contact mail.","Send from an external mailbox, verify receipt and configure a legitimate reply-from method if you need branded replies.","Forwarding alone does not give you an outbound mailbox. Check the reply sender and test threading before advertising support."],"SiteAPT":["Consider a compact website analytics and performance workflow when you manage multiple independent sites; Project Zero and SiteAPT share ownership.","Add a test site, install the provided script under your privacy choices and verify the public hostname and tracking configuration.","Generate a controlled visit and check page title, path and referral reporting; distinguish test traffic from genuine customers.","If reports stay empty, inspect browser blocking, consent choices, script delivery and site mapping before concluding there is no traffic."],"Google Analytics":["Consider when detailed marketing attribution and event measurement are important; configure data collection deliberately rather than enabling everything.","Create a test property and stream, define the handful of events tied to actual business outcomes, and implement appropriate consent controls.","Verify events using controlled visits, exclude sensitive parameters and compare counts against your own order records.","A pageview count is not a sales count. Validate conversion event triggers for duplicates and cross-domain checkout behavior."],"Plausible":["Consider a simpler website measurement workflow focused on aggregate traffic and goal outcomes rather than highly granular profiling.","Set up a site, add the documented tracking script according to your privacy choices and define one useful conversion event.","Visit a controlled page and trigger the event; compare the expected path and source with the dashboard.","Tracking blockers and consent may affect counts. Do not infer exact unique individuals from aggregate analytics."],"Cloudflare Web Analytics":["Useful for a lightweight view of page traffic and performance when your site is in the Cloudflare ecosystem.","Configure the correct hostname and use the documented beacon or integration where appropriate; avoid duplicate trackers.","Run controlled visits from mobile and desktop and compare performance metrics with the pages tested.","If traffic looks missing, check hostname, beacon delivery and browser settings; requests at the network edge and page views are different measurements."],"Google Search Console":["Use for understanding search discovery, impressions and indexing; it does not replace conversion analytics.","Verify the intended domain or URL property, submit the canonical sitemap and inspect a representative public page.","Check index coverage, search queries and canonical selection over time; document changes before evaluating results.","Submitting a sitemap does not guarantee indexing. Check status codes, crawl access, canonical tags and usefulness of the actual page."],"Matomo":["Consider self-hosting when control of analytics infrastructure is important, or managed hosting if maintenance is not justified.","Set up a distinct site ID, configure retention and anonymization/privacy controls, then install tracking in staging.","Verify visits and goals, test exclusion of sensitive parameters and plan database backups and upgrades.","Slow reports may reflect data retention, archiving jobs or database load. Monitor resource requirements as event volume grows."],"Sentry":["Useful for identifying application errors and their release context. Limit data collection and scrub customer or credential fields.","Add the SDK to staging, configure the correct project/environment and release tag, then trigger a controlled exception.","Check grouping, source map handling, alert thresholds and sensitive data filtering. Verify a known fix stops the error.","If errors lack stack context, inspect build artifact/source map upload and release identifiers before increasing event volume."],"Better Stack":["Consider combined uptime, logs or incident workflows if centralized alerts reduce operational overhead.","Set up a test monitor and log source with separate credentials. Configure thresholds and routing to someone who can act.","Simulate a brief failure, verify notification and recovery, and review retention and ingestion limits.","Noisy alerts train operators to ignore failures. Separate actionable customer-facing outages from transient internal warnings."],"UptimeRobot":["Useful for checking availability of public websites or health endpoints from outside your hosting environment.","Create a monitor for a stable HTTPS endpoint and choose an interval and notification recipient appropriate to business impact.","Test a controlled unhealthy staging response and confirm recovery messages. Check certificate and region behavior as needed.","A homepage returning HTTP 200 does not prove checkout or login works. Use a meaningful separate health endpoint or synthetic workflow."],"Cloudflare Observability":["Consider native Worker metrics and logs for edge applications; avoid recording request bodies or personal information unnecessarily.","Enable only required logging, include request correlation and release context, and use non-sensitive error categories.","Trigger a known error, find the corresponding trace or log and compare request/error counts with expected traffic.","If logs are expensive or noisy, adjust sampling and retention after preserving enough evidence to troubleshoot important errors."],"GitHub Actions":["Good for reproducible repository checks and deployments. Use separate permissions for testing and for publishing.","Create a workflow for pull requests with locked dependencies and tests. Restrict token permissions and use environment secrets only in authorized jobs.","Run a deliberately failing test and confirm it prevents release; require a reviewed branch before production deployment.","If a workflow fails only in CI, compare runtime version, environment variables, operating system and working directory."],"GitLab CI/CD":["Consider when your team already manages source and pipelines in GitLab or needs a coordinated build-and-release process.","Define pipeline stages and runner requirements, separate test from deploy jobs, and mark sensitive variables appropriately.","Confirm merge requests trigger tests and production publishing requires the intended policy; inspect retained artifacts for secrets.","A stuck job may have no matching runner or tags. Check runner health and job configuration before relaxing permissions."],"Cloudflare Workers Builds":["Useful for Git-driven Worker build workflows when deployment should follow tested source changes.","Connect the intended repository and configure root directory, build command and deploy command for the Worker.","Validate a preview or staging release, keep configuration scoped per environment, and test rollback to a known-good version.","If deployment succeeds but runtime bindings fail, inspect the configuration used by the build rather than adding secrets to tracked source."],"Shopify":["Choose hosted commerce if managing products, variants, checkout, shipping and orders in one service is more valuable than running your own store stack.","Start with one clear product and accurate variants, price, stock, images, delivery window and return policy. Choose a simple theme and test the mobile product page.","Configure business settings, shipping, taxes and eligible payment methods; run a test transaction and verify order notifications and fulfillment routing.","If checkout says a variant is unavailable, compare the storefront's selected variant and Shopify inventory or fulfillment state. Never advertise a product combination you cannot deliver."],"WooCommerce":["Consider if you already run WordPress and want control over the storefront and extensions; budget for maintenance, hosting and update compatibility.","Use staging, install WooCommerce on a supported WordPress setup and create a limited initial product catalog.","Configure shipping and payments, test checkout and email, and take a restorable backup before updating extensions.","Plugin conflicts often affect cart or payment behavior. Reproduce on staging with the same versions and isolate changes one at a time."],"Printify":["Useful for print-on-demand experiments where supplier production replaces holding inventory. You still own merchandising, policy and support decisions.","Choose a product and supplier, calculate landed costs, order a sample and map every size/color to a real supplier variant.","Connect the approved sales channel, validate shipping estimates and exercise order routing in a controlled test without unintentionally purchasing.","A storefront may advertise a variant a supplier no longer offers. Recheck mappings and availability, and keep product specifications synchronized."],"GitHub Releases":["Useful for versioned distribution of public software; consider private access and separate download infrastructure for paid apps.","Create a tagged release from a reviewed commit, build reproducible artifacts and publish platform-specific files with checksums and release notes.","Verify downloads and checksums on clean machines; test updater behavior and ensure signing keys never enter the repo.","If an updater installs the wrong file, check its OS/architecture selection and version manifest rather than renaming artifacts after release."],"Apple Developer":["Necessary for many Apple distribution workflows. Plan signing, notarization or App Store review based on the intended distribution channel.","Confirm account ownership and target platforms; configure bundle identifiers and signing with protected keys.","Build and test on real supported devices, review privacy disclosures, and follow the applicable submission or notarization requirements.","Installation refusal may come from signing, entitlements or OS incompatibility. Inspect the exact system error before asking users to bypass security."],"Google Play Console":["Use when distributing Android applications through Google Play; verify account type, release and testing requirements.","Set up the owner-controlled account, configure app identity and signing, and prepare store listing and data disclosures matching the app.","Use the appropriate internal or closed testing track; exercise fresh installs, upgrades, permissions and purchase restoration if relevant.","Review rejection often requires correcting actual app behavior or disclosures, not merely changing listing text."],"Microsoft Partner Center":["Use when the Windows distribution channel requires its publisher registration or store workflows. Separate store requirements from direct-download signing.","Choose the correct publisher account, register app identity and prepare a supported package and listing.","Test clean install, updates, accessibility and entitlement behavior; record package identifiers and supported Windows versions.","If a package fails certification, reproduce the reported issue with the submitted build and fix the cause before resubmitting."],"Google Ads":["Consider only after conversion tracking and unit economics are reliable. A campaign can spend money before it produces useful demand.","Define a specific conversion and landing page, choose a small approved test budget and tightly match keywords to customer intent.","Check search terms, conversion duplicates and cost per acquisition; compare against contribution margin rather than gross revenue.","Low click cost does not imply profitability. Pause wasteful queries and repair broken conversion tracking before scaling."],"Google AdSense":["Consider for content with original value and suitable audience demand; site approval and ad revenue are not guaranteed.","Prepare substantive content, navigable pages, policies and site ownership verification; review publisher eligibility and placement rules.","Check consent requirements, mobile layout and page speed, and verify ads only after approval without clicking your own ads.","If approval is withheld, review the stated reason and content quality before resubmitting; avoid adding artificial traffic."],"Mailchimp":["Consider email marketing if you have an opted-in audience, a publishing cadence and a measurable business goal.","Create an audience with consent provenance, authenticate the sender and build a welcome message with a working unsubscribe.","Test signup, unsubscribe and segmentation using controlled addresses, then monitor bounces and list growth.","Duplicate contacts and unengaged lists can inflate costs. Remove duplicates and respect suppression rather than buying lists."],"Kit":["Useful for creator newsletters and audience workflows centered on content and segmentation.","Create a signup form and tags for the actual reader interests; authenticate sending and publish a relevant welcome email.","Test signup confirmation where used, unsubscribe and a small automated sequence, checking links and mobile rendering.","If a sequence sends twice, inspect entry rules and tags; do not repeatedly resubscribe people who opted out."],"Help Scout":["Consider a shared inbox when support email must have ownership and response history without a complex service desk.","Create a mailbox connection, define staff permissions and establish status/assignment conventions.","Send a controlled test message, reply from the expected sender and verify that replies join the same conversation.","If replies are missing, inspect forwarding and mail headers rather than asking users to start new threads."],"Freshdesk":["Useful when tickets, categorization and response targets matter across multiple support agents.","Set up a support channel with owner permissions, minimal ticket fields and routing based on actual support categories.","Test intake, assignment, escalation, customer reply and closure with a dummy case; ensure agents cannot see unrelated restricted data.","When tickets duplicate, check overlapping forwarding rules or integrations before automating more intake channels."],"Zendesk":["Consider structured multi-channel support when business volume warrants the complexity. Compare agent costs and required features.","Configure a limited support channel, roles and ticket workflow; add only necessary custom fields and automation.","Test customer reply, assigned agent response and reopening after closure; export a test ticket for recovery or migration planning.","Automated rules can conflict or loop. Trace the sequence of ticket events and simplify routing before adding another trigger."],"GitHub":["Use source control as the record of code changes, issues and releases rather than storing passwords or production exports.","Create the repository with the right visibility, branch protection and a reproducible README. Use a .gitignore and a secret-scanning workflow.","Open a pull request, require checks and review, and practice reverting a harmless change. Confirm access for maintainer accounts.","If a key is committed, treat it as exposed and rotate it; deleting the line in a later commit does not remove earlier history."],"ChatGPT":["Consider an assistant for drafting, planning, debugging and reviewing well-defined work, with human oversight for consequential changes.","Provide the project brief, current source of truth, acceptance criteria and non-secret relevant context. Ask for scoped changes rather than broad rewrites.","Review diffs and run tests; independently verify current API facts and production results. Keep deployment and spending permissions explicit.","A confident answer can be wrong. Require evidence, reproduction steps and explicit unresolved limitations rather than trusting a completion claim."],"Claude":["Consider an assistant for code review, implementation planning and longer technical documents; choose access based on task requirements.","Provide the repository or task context and constraints, including boundaries for production changes and sensitive data.","Ask for small reviewable patches and test evidence; check assumptions and coordinate with other contributors before merging.","If separate agents edit the same file, pause and reconcile current branches. Never treat a generated recommendation as verified deployment."]};
const CATEGORY_COSTS={"hosting":"A site with 10,000 pageviews may make many more asset and API requests. Measure a representative page and multiply by expected visits; separate compute, bandwidth, build and persistent storage. Check the idle bill, peak bill and rollback procedure.","domains":"Calculate three-year ownership as registration plus two renewals and any DNS or forwarding extras. Keep ownership in your own account and note expiration; compare transfer restrictions and preserve mail records during any change.","database":"Design the largest expected table and the three queries used most often. Estimate rows read or documents fetched, storage growth and outbound traffic; include backups and restoration time. Test an unauthorized tenant and a restore.","storage":"Estimate average object size times retained object count, then multiply download size by expected downloads to model transfer. Count writes, reads and retrieval charges separately; evaluate retention and recovery instead of relying on a public bucket.","identity":"Estimate active users, organizations, login methods and required security features. Test two independent accounts; the authentication bill is separate from application authorization work and staff access management.","payments":"Compare total fees at the actual average transaction size and number of sales. Include fixed and percentage fees, subscriptions, refunds and obligations for taxes and refunds; reconcile actual payout with the order ledger.","email":"Estimate monthly operational messages, marketing and staff seats separately. Add a realistic retry allowance, authenticate sending domains, test bounces and determine who handles customer replies.","analytics":"Define business decisions before choosing metrics. Estimate pageviews and events from realistic traffic; verify privacy choices and data retention. Compare conversions against the authoritative transaction or form record.","monitoring":"Count critical endpoints, check cadence and expected error/log volume. Test a controlled failure; expensive logs and noisy alerts are not a substitute for knowing when customers cannot complete a transaction.","ci":"Estimate jobs per pull request times average run duration, plus builds and retained artifacts. Use pinned dependencies and a separate scoped deploy job; ensure failed checks prevent an authorized release.","commerce":"Model contribution after product, fulfillment, payment fees, returns, discounts and advertising. Divide recurring expenses by contribution per order for break-even and check expensive variants separately.","distribution":"Estimate release size, downloads, signing and store requirements, support and payment costs. Test installation and upgrades on supported devices before charging customers; verify license and refund handling.","marketing":"Start with one measurable audience and customer action. Compare customer acquisition cost with contribution margin, include subscription fees and avoid purchased traffic or email lists that cannot produce genuine customers.","support":"Estimate ticket volume, agent seats, time to respond and customer data retention. Test intake, replies, assignment and closure; use a mailbox you control and document escalation.","assistants":"Estimate the time saved on a repeatable task versus subscription and review costs. Keep source control authoritative, avoid sharing credentials and require independent tests and evidence before changes reach production."};
const COMPARISON_EDITORIAL={"cloudflare-vs-vercel-vs-netlify":["A marketing website with prebuilt HTML is primarily a build-and-delivery problem; an authenticated dashboard is also a runtime and data problem. Try deploying the same small page and one server route to a preview before choosing. Compare cold starts, supported runtime APIs, branch previews, environment separation and commercial eligibility. For a revenue-generating project, include build minutes, requests, compute and transfer rather than assuming a free tier is always suitable.","For an existing Next.js app, test a dynamic route, caching and image handling in each environment. For a static brochure, prefer the option requiring the fewest separate services. For an edge API using Cloudflare storage, verify runtime compatibility and binding behavior."],"cloudflare-vs-digitalocean-vs-render":["These services can solve different problems: request-driven edge code, a general-purpose VM or a managed application process. A persistent background worker or custom binary may not fit a request-driven runtime. A VM gives control but requires OS maintenance, a firewall, patches and recovery. A managed service trades some control for operational convenience.","Deploy a small endpoint that exercises the real runtime and database connection. Measure memory/CPU, idle cost, startup, concurrency and data persistence after restart. For always-on work compare the bill at both idle and peak usage; include backups and the cost of the operator's time."],"stripe-vs-paddle-vs-lemon-squeezy":["Payment processing and merchant-of-record services are not interchangeable. Compare who sells to the customer, who handles applicable taxes and refunds, which products and countries are eligible, and who owns subscription or license delivery. Check the specific product offered, not just the provider brand.","Model 100 sales at $20 with two hypothetical models: 3% + $0.30 costs $90; 5% plus $0.50 costs $150. The $60 difference is meaningful only after comparing included services and obligations. These rates are examples, not quotes. Run successful and failed payments, refunds and duplicate webhook events in each candidate's sandbox."],"d1-vs-supabase-vs-firebase":["Choose the data model before the platform: SQLite-compatible relational queries, PostgreSQL relations and constraints, or a document-based model designed around access patterns. The best database is the one that supports your actual queries, tenant permissions and recovery needs.","Create a realistic sample of 10,000 records and retrieve one customer's newest 20. Compare query complexity, scanned or billed reads, indexes, network latency and authorization. Restore a sample backup into an isolated project before committing to a migration."],"r2-vs-s3-vs-backblaze-b2":["Object storage is useful for images, uploads, backups and release assets; it is not a database or automatic CDN. Compare application integration, regional requirements, API compatibility, retrieval costs, requests, retention and access control.","For a 500 MB downloadable product with 200 monthly downloads, transfer is about 100 GB before retries and update downloads. Model a busy month as well as a quiet one. Test one signed download, a denied anonymous request and a restored archived object with all three providers' applicable workflows."],"resend-vs-postmark-vs-sendgrid":["Distinguish transactional mail from marketing campaigns and normal staff inboxes. Evaluate deliverability tooling, domain setup, webhooks, suppression and message retention. Avoid basing the decision on advertised maximum volume alone.","For 1,000 accounts generating an average of four operational emails monthly, estimate 4,000 sends before reminders and retries. Test confirmation, bounce and complaint handling with a controlled domain, and confirm staff can respond using a real reply-to mailbox."],"shopify-vs-woocommerce-vs-printify":["Shopify and WooCommerce are storefront options; Printify is a fulfillment service that can be used with a storefront. Comparing the three as interchangeable ecommerce platforms misses the key decision. Choose the storefront first and use print-on-demand only if it fits your product and margins.","For a shirt business, model the actual garment, shipping and platform costs per variant. Hosted commerce can reduce maintenance; a self-managed store can offer more control but adds plugin, backup and update risk. Take one sample order from product page to fulfillment and customer support before investing in advertising."]};
const HOWTOS=[{"slug":"shopify-store-setup","title":"How to start a Shopify store from scratch","type":"commerce","providers":["Shopify","Printify","Stripe"],"desc":"Build a launch-ready store with one product, a working checkout and clear fulfillment terms.","budget":"Before signing up, estimate landed cost, expected demand, recurring storefront and app charges, and reserve for returns. Use real supplier quotes.","steps":[["Plan the first product","Pick one customer and a product they can buy today. Record an SKU, physical dimensions, color and size variants, images, price and inventory. Write delivery and returns language that matches your supplier."],["Set up the storefront","Create the store account, complete business settings, choose a simple theme and add a product with a descriptive title and original description. On mobile, confirm the variant picker changes the pictured or labeled variant correctly."],["Configure delivery and checkout","Define shipping zones, delivery estimates, taxes and eligible payments. Set automatic discounts only when margins still work. Add contact, refund and privacy pages and link them in the footer."],["Connect the domain","Set your primary domain in the store admin and make the DNS changes specified by Shopify. Preserve mail records and verify HTTPS and redirects."],["Run a test order","Use supported test payment mode, confirm the order appears in admin, check confirmation email and fulfillment routing, then return the payment gateway to the intended live configuration. Do not trigger an actual shipment without intending to."]],"tests":["Every selectable variant can be fulfilled","Checkout total matches advertised shipping and discounts","Test order reaches the correct order system","Mobile product and policy pages work"],"fix":"If checkout rejects an item, inspect its variant availability and shipping zone before changing your theme.","source":"https://help.shopify.com/en/manual/intro-to-shopify/initial-setup/new-to-shopify-checklists/general-checklist"},{"slug":"shopify-print-on-demand","title":"How to start a print-on-demand store with Shopify and Printify","type":"commerce","providers":["Shopify","Printify","WooCommerce"],"desc":"Connect a storefront to a print supplier and verify that actual margins and fulfillment work.","budget":"Example only: a $30 shirt with $12 production, $5 shipping, $1.20 fees and $2 returns reserve contributes $9.80 before fixed costs and taxes.","steps":[["Find a product and supplier","Select a garment or item with a known size chart, print area, production location and estimated shipping. Order a sample to judge the actual print, fit and packaging before advertising."],["Price the item","Include all production and fulfillment charges, payment fees, discounts, replacements and returns. Compare contribution for each size or region instead of averaging away expensive variants."],["Connect the sales channel","Authorize only the necessary store access, create a draft product and map each color and size to a valid supplier SKU. Set the exact images, measurements and customer-facing delivery language."],["Verify order flow","Use a supported controlled test and make sure order identifiers, customer address and selected variant reach the supplier correctly. If automatic purchasing is on, disable it for any test that must not ship."],["Launch and monitor","Publish only available variants, review delivery and customer support, and reconcile supplier charges against each order. Remove outdated variant mappings before customers see them."]],"tests":["Sample quality meets expectations","Actual contribution stays positive","Every product option maps to a supplier SKU","Support can answer a shipment inquiry"],"fix":"If an item becomes unavailable, hide that option in the storefront and confirm the replacement mapping rather than accepting unfulfillable orders.","source":"https://printify.com/"},{"slug":"shopify-custom-domain","title":"How to connect a custom domain to Shopify","type":"domains","providers":["Shopify","Cloudflare Registrar","Namecheap"],"desc":"Move your store to a branded hostname without breaking checkout or email.","budget":"Use an existing domain when possible; budget for renewal rather than the first-year promotion.","steps":[["Inventory DNS","Export or record the authoritative DNS configuration first. Identify current A, AAAA, CNAME, MX and verification TXT records and who controls them."],["Add the domain in Shopify","In domain settings choose the option to connect an existing domain and record the exact records requested for your account. Do not copy outdated IP examples from another blog."],["Edit DNS carefully","At the authoritative DNS provider replace only conflicting web records. Keep existing mail and authentication records. Allow DNS caches time to refresh."],["Verify the store","Wait for the domain connection and certificate to become active. Set the intended primary domain and visit both apex and www versions on a different network."],["Test checkout and account links","Open a product, add a real available variant to the cart, and reach checkout. Check password reset, order links and policy URLs point to the correct public domain."]],"tests":["Primary hostname loads with HTTPS","Other web hostnames redirect correctly","Mail continues to work","Checkout and customer links resolve"],"fix":"If domain verification succeeds but HTTPS fails, follow the provider's certificate instructions and check for conflicting records; avoid cycling DNS changes.","source":"https://help.shopify.com/en/manual/intro-to-shopify/initial-setup/setup-getting-started"},{"slug":"shopify-seo","title":"How to improve Shopify SEO for product and collection pages","type":"marketing","providers":["Shopify","Google Search Console","SiteAPT"],"desc":"Make store products easier to find in search and easier to buy on mobile.","budget":"Start with organic improvements; paid ads are optional and do not guarantee organic rankings.","steps":[["Choose search intent","Group real products by what customers search for: product type, use, style and material. Give each indexable collection a clear purpose rather than generating near-duplicate categories."],["Write useful product pages","Use a descriptive product title, original description, sizing and material information, delivery details and meaningful image alt text. Answer questions that affect buying decisions."],["Inspect technical SEO","Check canonical URLs, links from collections, indexable product pages and redirects after handle changes. Verify the public sitemap and avoid indexing duplicate filter combinations unnecessarily."],["Verify discovery","Add your store to Search Console and submit its sitemap. Inspect representative collection and product URLs, then track impressions, clicks and indexing."],["Improve with evidence","Review query terms, click-through rates, mobile usability and conversions. Change a small group of pages, record the date and compare like-for-like periods before repeating."]],"tests":["Product and collection URLs return 200","Titles and descriptions match content","Sitemap lists canonical public pages","Mobile checkout works"],"fix":"If pages are not indexed, inspect canonical selection and crawl access first. Sitemap submission alone does not guarantee indexing.","source":"https://developers.google.com/search/docs/fundamentals/seo-starter-guide"},{"slug":"cloudflare-pages-website","title":"How to deploy a static website on Cloudflare Pages","type":"hosting","providers":["Cloudflare","GitHub","Cloudflare Registrar"],"desc":"Publish a small static site from Git with previews, a custom domain and rollback.","budget":"Budget for domain renewal and confirm current hosting limits and commercial terms.","steps":[["Prepare a repository","Create a project containing an index.html or framework source, assets and instructions. If you use a build tool, run its production build locally and note the generated output directory."],["Connect Git","In Workers & Pages create a Pages project using the Git integration. Authorize the correct repository, select the production branch and configure framework build command and output directory."],["Inspect the first deployment","Read the build log and open the preview URL. Check CSS and image links, direct visits to service pages and mobile layout. Fix source and push another commit when needed."],["Attach the domain","Add the custom domain from the Pages project and follow the specified DNS steps. Verify HTTPS and choose one canonical hostname; preserve existing mail records."],["Test future changes","Create a branch with a harmless change and inspect its preview before merging. Record the last known-good deployment and practice rollback before relying on the site for sales."]],"tests":["Preview and production work","Correct domain loads over HTTPS","Assets and nested links return 200","A branch preview does not overwrite live content"],"fix":"A blank page often means the wrong output directory or asset path. Inspect the emitted files and build log.","source":"https://developers.cloudflare.com/pages/get-started/git-integration/"},{"slug":"digitalocean-droplet","title":"How to set up a DigitalOcean Droplet for a small web app","type":"hosting","providers":["DigitalOcean","Cloudflare","UptimeRobot"],"desc":"Create and secure a Linux VM for an application that needs a persistent server.","budget":"Estimate compute, backups, data transfer, domain and any persistent volumes. Check actual quotes; a static site may not need a VM.","steps":[["Choose the server","Measure your app's memory use locally, choose a suitable region and supported Linux image, and add your SSH public key when creating the Droplet. Never upload the private key."],["Secure administrative access","Connect using SSH, update packages, create a non-root administrative user and validate access in a second session. Restrict SSH with a firewall before exposing the app."],["Deploy the app","Install the required runtime or container tooling from trusted sources. Run the application under a non-root account with secrets outside the repository. Arrange for it to restart on reboot."],["Serve HTTPS","Configure a reverse proxy, DNS and a valid certificate using supported instructions. Permit only required inbound ports and bind internal services to private interfaces."],["Prove recovery","Back up both data and configuration, monitor the public health endpoint, and restore a copy to a disposable environment. Verify cost notifications and remove unused test resources."]],"tests":["SSH key access works","Database ports are not public","App survives reboot and TLS works","Backup restore is tested"],"fix":"For a timeout, check the app listener, local firewall, cloud firewall and proxy logs before altering DNS.","source":"https://docs.digitalocean.com/products/droplets/getting-started/recommended-droplet-setup/"},{"slug":"custom-domain-dns","title":"How to connect a domain to a website and configure DNS","type":"domains","providers":["Cloudflare Registrar","Namecheap","Porkbun","Cloudflare"],"desc":"Understand A, CNAME, MX and TXT records before changing a live domain.","budget":"The domain renewal and hosting charges are separate; record both.","steps":[["Find authoritative DNS","Look up the nameservers and determine which service currently answers queries. Export or document records, including mail and verification values."],["Get hosting requirements","Ask the host for the exact apex and www configuration. Use an A or AAAA record for an address and a CNAME where the provider instructs; some hosts support apex aliases."],["Preserve unrelated services","Update only the required web records and avoid deleting MX, SPF, DKIM, DMARC or validation TXT records. If migrating DNS providers, recreate the full zone before switching nameservers."],["Verify from outside","Check DNS responses from multiple networks, then load the site over HTTPS. Follow the host's certificate-validation process and confirm apex and www redirects."],["Plan rollback","Retain old DNS values and the old working host until the new service has been verified. Test mail and critical forms as well as the homepage."]],"tests":["Authoritative nameservers are correct","HTTPS works on canonical host","Email delivery works","Old settings are documented"],"fix":"Editing records at the registrar will not help if another provider is authoritative. Resolve nameservers first.","source":"https://developers.cloudflare.com/pages/configuration/custom-domains/"},{"slug":"google-search-console","title":"How to set up Google Search Console and submit a sitemap","type":"analytics","providers":["Google Search Console","SiteAPT"],"desc":"Verify a website, submit its sitemap and investigate pages missing from search.","budget":"Search Console setup itself does not require ad spending; budget time for fixing actual crawl issues.","steps":[["Choose the property","Decide whether to verify the domain including subdomains or a specific URL prefix. Use the method supported for that property and an owner-controlled Google account."],["Verify ownership","For DNS verification, add the exact TXT record at authoritative DNS and complete verification in Search Console. Preserve the record and avoid publishing private account credentials."],["Check the sitemap","Open the sitemap directly, confirm valid XML with absolute canonical public URLs and HTTP 200 responses. Exclude sign-in, private or redirected pages."],["Submit and inspect","Submit the sitemap URL within the appropriate property. Inspect a representative public page and review canonical selection, crawl access and indexing status."],["Establish a routine","Review clicks, impressions and query/page performance on comparable date ranges. Fix problems that prevent customers reaching useful pages rather than chasing every warning."]],"tests":["Property owner verified","Sitemap accepted","Representative URLs inspected","Private routes remain excluded"],"fix":"If a sitemap is fetched but a URL is not indexed, check the specific page's indexing report and content; repeated submissions are not a cure.","source":"https://developers.google.com/search/docs/crawling-indexing/sitemaps/overview"},{"slug":"stripe-subscription-checkout","title":"How to set up recurring subscription checkout with Stripe","type":"payments","providers":["Stripe","Paddle","Lemon Squeezy"],"desc":"Implement subscription checkout with server-side access and reliable billing updates.","budget":"Model transaction and subscription fees, refunds, tax obligations and fixed service costs using current official rates.","steps":[["Define plans and entitlements","Write down price, billing interval and exact features or limits. Create corresponding test-mode products and recurring prices, and store the allowed price IDs server-side."],["Create checkout","Create a checkout session on a trusted backend after verifying the user and allowed plan. Associate the session with the app account; never trust a client-supplied amount."],["Process billing events","Validate the webhook signature against the raw request body, deduplicate event IDs and record updates to authoritative subscription state. Handle out-of-order delivery by checking current object state when needed."],["Enforce access","Use the subscription state and effective access dates on the server to decide what the customer can use. Support cancellation, payment failure and recovery according to a documented policy."],["Verify before launch","Exercise successful, declined, renewed and canceled subscriptions using test tools. Confirm a duplicate event does not create another account or entitlement. Set up reconciliation and a support path."]],"tests":["Test purchase activates correct access","Cancellation follows defined effective date","Duplicate event is harmless","Refund and failure paths are documented"],"fix":"If a customer paid but has no access, check webhook delivery, signature validation and the internal account association.","source":"https://docs.stripe.com/"},{"slug":"transactional-email-domain","title":"How to authenticate a domain for transactional email","type":"email","providers":["Resend","Postmark","SendGrid","Amazon SES"],"desc":"Set up sending for confirmations and account messages with DNS authentication and bounce handling.","budget":"Choose a sending service based on message volume and operational requirements; budget separately for staff mailboxes.","steps":[["Choose your sender","Use a domain or subdomain controlled by your business and a real reply-to address. Separate marketing from account or order messages when appropriate."],["Add verification records","Copy the exact records given by your email provider to the authoritative DNS. Review existing SPF before adding records to avoid conflicting policies; add the specified DKIM and return-path configuration."],["Configure the backend","Store the sending key as a server secret, restrict its scope, and build templates with escaped customer-provided content. Do not expose keys in frontend bundles."],["Send a controlled message","Send from staging to an address you control. Inspect delivery status and authentication results, and verify links and the reply destination."],["Handle failures","Consume delivery events with validation and deduplication, suppress invalid recipients and log non-sensitive failures. Review DMARC reporting and enforce stronger policies deliberately after identifying legitimate senders."]],"tests":["Domain verified by provider","Test email arrives","Reply-to reaches support","Bounce cannot trigger endless retries"],"fix":"An API success only means the service accepted the message. Check provider events and recipient headers before diagnosing spam.","source":"https://resend.com/docs"},{"slug":"website-uptime-monitoring","title":"How to monitor website uptime and recover from outages","type":"monitoring","providers":["UptimeRobot","Better Stack","Sentry"],"desc":"Create availability checks that notify you only when useful action is needed.","budget":"Estimate monitor count, check interval and log retention; start with critical customer paths.","steps":[["Select endpoints","Monitor the public homepage and a lightweight health URL that reflects critical dependencies without exposing sensitive information. Choose a separate staging endpoint for failure tests."],["Set expectations","Configure HTTPS and status checks with suitable timeout, location and interval. Add confirmation rules if a single transient failure should not page you."],["Route alerts","Assign notifications to an owner who can act. Include URL, timestamp and symptom, not customer credentials or raw request bodies."],["Test an incident","Make a staging health check fail intentionally, verify the alert reaches the owner, restore normal behavior and confirm recovery notification."],["Write recovery steps","Document where logs and deploy history live and how to restore the last working version. After real outages, record root cause and a prevention step."]],"tests":["Probe checks the intended hostname","A controlled failure sends an alert","Recovery is visible","Rollback documented"],"fix":"A healthy homepage can coexist with a broken login or checkout. Monitor the actual customer-critical dependency where safe.","source":"https://uptimerobot.com/"},{"slug":"website-analytics-setup","title":"How to install website analytics and measure conversions","type":"analytics","providers":["SiteAPT","Google Analytics","Plausible"],"desc":"Measure visits and meaningful customer actions without collecting unnecessary sensitive data.","budget":"Decide what you need to measure before buying a plan; confirm limits and privacy obligations.","steps":[["Define decisions","Choose a few outcomes such as contact submissions, successful purchases or documentation downloads. Record an exact event name and trigger for each."],["Choose and install a tracker","Create a property for the real hostname and follow the provider's installation instructions. Build appropriate consent controls and avoid putting sensitive fields into events."],["Verify a controlled session","Visit several pages from a known browser, trigger a test conversion and check that page path, referral and event appear once. Test a declined-consent session separately."],["Reconcile outcomes","Compare purchases with the order system and contact events with legitimate submissions. Never treat an analytics event as the authority for a financial transaction."],["Review and improve","Use comparable time ranges and segment by page or acquisition source. Identify pages with demand but weak conversion and test one meaningful improvement."]],"tests":["Test event appears once","Sensitive forms are not recorded","Consent behavior is verified","Revenue is reconciled separately"],"fix":"If the tracker is blocked, distinguish privacy controls from configuration errors; do not bypass a visitor's preference.","source":"https://siteapt.app/"},{"slug":"github-actions-ci","title":"How to create a GitHub Actions test workflow","type":"ci","providers":["GitHub","GitHub Actions","Cloudflare Workers Builds"],"desc":"Automatically check changes before they reach production without giving every job deploy permissions.","budget":"Check runner minutes and artifact/storage limits for the repository's visibility and plan.","steps":[["Make tests reproducible","Document the runtime, install command and test command. Commit a dependency lockfile and make sure the project can be tested without production secrets."],["Create the workflow","Add a workflow under .github/workflows that runs on pull requests and pushes to the intended branch. Check out the code, install the pinned runtime, install locked dependencies and run checks."],["Reduce permissions","Set the workflow token to only the permissions actually needed, avoid running untrusted changes with secrets and prefer pinned trusted actions."],["Require checks","Open a test pull request and deliberately fail a test, then fix it. Require the passing check for protected branches where supported."],["Separate deployment","Create an authorized deployment job only after tests pass. Use scoped secrets, staging and a known rollback so a code review does not automatically mean a production release."]],"tests":["Pull request triggers check","Failing test blocks authorized release","No production key in logs","Known-good release can be restored"],"fix":"If local tests pass but CI fails, compare runtime, lockfile, working directory and missing test configuration.","source":"https://docs.github.com/en/actions"},{"slug":"database-backup-restore","title":"How to back up a database and test recovery","type":"database","providers":["Supabase","Cloudflare D1","Neon","Backblaze B2"],"desc":"Create a recovery workflow that proves data is usable, not merely that a backup file exists.","budget":"Include backup retention, storage, restore duration and operator time; budget for a separate recovery environment.","steps":[["Define recovery requirements","Determine how much recent data can be lost and how long the business can be unavailable. Identify tables, schemas, files and configuration required for recovery."],["Use supported backup methods","Choose an export or managed backup that captures consistent data. Protect credentials, encrypt sensitive exports and store copies separately from the active environment."],["Record evidence","Keep the backup timestamp, schema version and expected test row counts or checksums. Avoid exposing contents in logs."],["Restore to isolation","Create a disposable environment and restore there, not over the live database. Apply necessary migrations and verify sample records, relationships and application queries."],["Schedule drills","Record restore duration, missing dependencies and what went wrong. Fix the process and document who may initiate recovery of real production data."]],"tests":["Backup contains required data","Restore succeeds in isolation","Application queries work","Recovery duration is measured"],"fix":"If relational records restore but attachments are missing, include the object store and its references in your recovery scope.","source":"https://supabase.com/docs"},{"slug":"private-file-downloads","title":"How to deliver private digital downloads with object storage","type":"storage","providers":["Cloudflare R2","Amazon S3","Backblaze B2"],"desc":"Store digital products privately and grant downloads only after authorized purchase.","budget":"Estimate storage, requests and transfer under realistic file sizes and repeated downloads.","steps":[["Choose object keys","Use versioned opaque keys for artifacts. Record file size, checksum and supported platform. Keep user names and order details out of object names."],["Create private storage","Set a private bucket and scope the application credential to required objects and operations. Test that anonymous access is denied."],["Authorize delivery","Verify the customer's entitlement on your backend before generating a short-lived signed or protected download. Do not rely on a hidden frontend URL."],["Test edge cases","Try a valid customer, an unauthorized customer and an expired link. Verify byte integrity and interrupted download recovery, and avoid caching personalized authorization responses publicly."],["Maintain versions","Retain supported releases and clearly identify updates. Test revocation behavior and backup recovery; document how customers get help if a download fails."]],"tests":["Anonymous request denied","Authorized download matches checksum","Expired access fails","Revocation policy works"],"fix":"A public bucket makes private product files accessible even if UI buttons require sign-in. Fix storage policy rather than obscuring the URL.","source":"https://developers.cloudflare.com/r2/"},{"slug":"secure-google-login","title":"How to add secure Google sign-in to a web app","type":"identity","providers":["Clerk","Auth0","Supabase Auth","Firebase Authentication"],"desc":"Configure identity and protect application routes rather than trusting a signed-in frontend.","budget":"Compare active-user charges, organization features and account recovery needs before picking a service.","steps":[["Register the application","Create the identity configuration for a dedicated staging app, set exact redirect and logout URLs and request only necessary scopes."],["Implement the login flow","Use the provider's maintained SDK and supported OAuth flow. Keep server credentials private and rely on the SDK for request integrity and token validation."],["Establish sessions","Validate identity on the server, use secure session cookies or appropriate tokens, and set expiration and logout behavior. Never store a client assertion as proof of identity."],["Authorize resources","Map authenticated users to internal account memberships and enforce those memberships on every protected read and write. Test two unrelated accounts."],["Ship safely","Check canceled consent, expired sessions, sign-out, recovery and direct API access. Review production callbacks and ensure no staging URLs are used for real customers."]],"tests":["Correct callback works","Wrong user denied","Expired session rejected","Logout clears app access"],"fix":"If login loops, inspect redirect URI and cookie configuration carefully; do not broaden callback domains or disable authorization.","source":"https://auth0.com/docs"},{"slug":"website-launch-checklist","title":"How to launch a business website without breaking SEO","type":"hosting","providers":["Cloudflare","Netlify","Google Search Console","SiteAPT"],"desc":"Prepare a public site for visitors, search discovery and operational recovery.","budget":"Estimate annual domain, hosting, email and maintenance costs before launch.","steps":[["Review the user journey","Open key pages on a phone and desktop. Test navigation, contact, forms and checkout if applicable. Add clear business and support information."],["Audit crawlability","Check HTTP status, one canonical URL per page, readable title and description, robots behavior, internal links and sitemap coverage. Keep admin and staging pages private."],["Check accessibility and speed","Use keyboard navigation, meaningful labels and image alternatives. Measure loading on realistic mobile conditions and address oversized images or blocking render resources."],["Protect the release","Review secrets, HTTPS, dependency updates and backups. Prepare an explicit rollback and confirm monitoring alerts reach an owner."],["Launch and observe","Publish the tested version, verify canonical pages from an external browser, submit sitemap and monitor actual traffic, errors and customer reports over the following days."]],"tests":["Critical journeys pass","Canonical sitemap is accessible","No production credentials embedded","Monitoring and rollback work"],"fix":"If search traffic drops after migration, inspect prior URL redirects and canonical mapping before changing all page titles.","source":"https://developers.google.com/search/docs/fundamentals/seo-starter-guide"},{"slug":"online-store-profit-margin","title":"How to calculate online store profit margins and break-even sales","type":"commerce","providers":["Shopify","Printify","PayPal","Stripe"],"desc":"Calculate contribution per order and use it to decide whether a storefront is commercially viable.","budget":"Use the worksheet and payment fee calculator with actual quotes rather than promotional rates.","steps":[["Calculate revenue","Start with the amount you retain from the product and customer-paid shipping. Exclude taxes collected for remittance and track discounts separately."],["Subtract variable costs","Include production, packaging, fulfillment, payment processing, returns reserve and per-order app fees. A $30 item with $20 variable costs has $10 contribution before fixed expenses."],["Calculate fixed expenses","List storefront fees, annual domain divided by twelve, monthly apps, software and support. If fixed expenses are $60 and contribution is $10, six sales cover fixed costs before any owner pay."],["Stress-test","Repeat the calculation for expensive variants, refunds, free shipping and discounts. Estimate paid acquisition separately and avoid campaigns where acquisition cost consumes all contribution."],["Measure actuals","Reconcile completed orders with supplier invoices and processor payouts. Compare actual versus expected contribution and update pricing or remove unprofitable products."]],"tests":["All variable costs included","Discounts modeled","Break-even uses contribution not revenue","Net proceeds reconciled"],"fix":"A high gross margin can hide shipping subsidies, returns and subscription costs; do not scale based on gross sales alone.","source":"https://www.shopify.com/"},{"slug":"shopify-test-checkout","title":"How to test Shopify checkout before opening your store","type":"commerce","providers":["Shopify","Printify","PayPal"],"desc":"Test cart, shipping, payment and order notifications without accidental live fulfillment.","budget":"Prefer the provider's test payment mode; a real transaction may incur fees or create a shipment.","steps":[["Prepare controlled products","Make sure each product and variant has a valid price, availability and delivery configuration. Disable automatic fulfillment for tests that must not ship."],["Enable supported test payments","Use Shopify's supported test transaction workflow for your payment configuration. Record the original configuration and avoid collecting real card details in test fixtures."],["Exercise customer paths","On mobile add different variants to the cart, apply expected discounts, enter representative shipping destinations and compare displayed totals with your policy."],["Verify backend effects","Confirm test orders, customer notifications and fulfillment routing. Test a decline or invalid input and verify it does not become a successful order."],["Restore and recheck","Return payments and automation to intended production settings. Inspect checkout from a signed-out browser to ensure test payment status is not accidentally left enabled."]],"tests":["Successful and failed paths verified","Totals match published policies","No unwanted shipment","Live payment configuration restored"],"fix":"An unavailable-item message is a catalog or fulfillment problem until proven otherwise; compare a rejected variant with the store's inventory.","source":"https://help.shopify.com/en/manual/checkout-settings/test-orders"}];
const DOCS={Shopify:'https://help.shopify.com/en/manual/intro-to-shopify/initial-setup',DigitalOcean:'https://docs.digitalocean.com/products/droplets/getting-started/',Cloudflare:'https://developers.cloudflare.com/', 'Google Search Console':'https://developers.google.com/search/docs',Stripe:'https://docs.stripe.com/'};
function howPath(t){return '/how-to/'+t.slug}
function howCards(list){return '<div class="grid">'+list.map(t=>'<a class="card" href="'+howPath(t)+'"><span class="mark">'+icon(t.type)+'</span><h3>'+esc(t.title)+'</h3><p>'+esc(t.desc)+'</p><small>Step-by-step instructions →</small></a>').join('')+'</div>'}
function relatedHow(list,heading='Step-by-step how-to guides'){return list.length?'<section><div class="sectionhead"><h2>'+esc(heading)+'</h2><a href="/how-to">All how-tos →</a></div>'+howCards(list)+'</section>':''}
function matchingHow(names,type){return HOWTOS.filter(t=>t.providers.some(n=>names.includes(n))||t.type===type).slice(0,6)}
function editorial(p){const d=Object.hasOwn(PROVIDER_EDITORIAL,p.name)?PROVIDER_EDITORIAL[p.name]:null;if(!d)return '';const [fit,first,verify,fix]=d;const more=matchingHow([p.name],p.category);return '<section class="editorial"><h2>When to choose '+esc(p.name)+'</h2><p>'+esc(fit)+'</p><h2>How to get started with '+esc(p.name)+'</h2><ol class="editorial-steps"><li><strong>Configure a small first project.</strong> '+esc(first)+'</li><li><strong>Validate before going live.</strong> '+esc(verify)+'</li></ol><h2>Budget and cost planning</h2><p>'+esc(CATEGORY_COSTS[p.category])+'</p><p><a href="/tools/website-budget-worksheet">Use the free website budget worksheet</a> to compare the expected recurring bill against your own spending ceiling before signing up.</p><h2>Common problems and how to fix them</h2><p>'+esc(fix)+'</p><p><a href="'+esc(DOCS[p.name]||url(p.url))+'" rel="noopener noreferrer" target="_blank">Official '+esc(p.name)+' setup resources ↗</a></p>'+relatedHow(more,'Practical tutorials for '+p.name)+'</section>'}
function howPage(path,ps){if(path==='/how-to')return page('How-to guides for starting and growing an online business | Project Zero','Step-by-step tutorials for ecommerce, Shopify, web hosting, DNS, SEO, payments, analytics and secure business operations.',path,'<section class="hero"><div class="kicker">Practical tutorials</div><h1>How to build, launch and grow your business</h1><p class="lead">Follow actionable steps, budget examples, troubleshooting advice and launch checks. Start with a real task, not another list of software subscriptions.</p></section>'+Object.entries(CATEGORIES).map(([k,c])=>{const list=HOWTOS.filter(t=>t.type===k);return list.length?'<h2>'+esc(c[0])+'</h2>'+howCards(list):''}).join(''),[{name:'How-to guides',path}],true,{'@type':'CollectionPage'});
const t=HOWTOS.find(t=>howPath(t)===path);if(!t)return null;const providers=t.providers.map(n=>ps.find(p=>p.name===n)).filter(Boolean);const shop=providers.find(p=>p.name==='Shopify');const referral=shop&&['shopify-store-setup','shopify-print-on-demand'].includes(t.slug)?approvedReferral(shop):null;const affiliate=referral?'<div class="pricing"><h2>Ready to create your store?</h2><p class="notice">'+esc(referral.disclosure)+'</p><div class="buttons"><a class="button" href="'+esc(referral.href)+'" rel="sponsored">Start with Shopify (affiliate link) ↗</a><a class="button secondary" href="'+esc(url(shop.pricing_url)||url(shop.url))+'" rel="noopener noreferrer">Check official pricing ↗</a></div><p><a href="/platforms/shopify">Read our full Shopify guide and alternatives</a> before choosing a plan.</p></div>':'';
return page(t.title+' | Project Zero',t.desc,path,'<article class="detail editorial"><div class="kicker">Step-by-step how-to</div><h1>'+esc(t.title)+'</h1><p class="lead">'+esc(t.desc)+'</p><div class="pricing"><h2>Before you start: cost and prerequisites</h2><p>'+esc(t.budget)+'</p><p><a href="/tools/website-budget-worksheet">Download the editable budget worksheet →</a></p></div><nav class="article-toc" aria-label="On this page"><strong>On this page</strong><ol>'+t.steps.map(([n],i)=>'<li><a href="#step-'+(i+1)+'">'+esc(n)+'</a></li>').join('')+'<li><a href="#verify">Verification checklist</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ol></nav><h2>Step-by-step instructions</h2>'+t.steps.map(([n,d],i)=>'<section class="tutorial-step" id="step-'+(i+1)+'"><h3>'+(i+1)+'. '+esc(n)+'</h3><p>'+esc(d)+'</p></section>').join('')+'<h2 id="verify">Verify your work</h2><ul class="checklist">'+t.tests.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><h2 id="troubleshooting">Troubleshooting</h2><p>'+esc(t.fix)+'</p>'+affiliate+'<h2>Official resources</h2><p><a href="'+esc(url(t.source))+'" rel="noopener noreferrer" target="_blank">Provider documentation and setup resources ↗</a>. Check current provider instructions and costs before making changes. <a href="/methodology">Editorial policy and disclosures</a>.</p></article><h2>Compare the tools used in this tutorial</h2><div class="grid">'+providers.map(card).join('')+'</div>'+relatedHow(HOWTOS.filter(x=>x!==t&&(x.type===t.type||x.providers.some(n=>t.providers.includes(n)))).slice(0,4),'Continue learning'),[{name:'How-to guides',path:'/how-to'},{name:t.title,path}],true,{mainEntity:{'@type':'Article',headline:t.title,description:t.desc,author:{'@type':'Organization',name:'Project Zero'},publisher:{'@type':'Organization',name:'Project Zero'},mainEntityOfPage:BASE+path}})}
function comparisonEditorial(c){const d=COMPARISON_EDITORIAL[c.slug];return d?'<h2>What actually matters for your business</h2><p>'+esc(d[0])+'</p><h2>Worked decision example</h2><p>'+esc(d[1])+'</p>'+relatedHow(matchingHow(c.names),'Put the comparison into practice'):''}
function setupEditorial(t){const d=CATEGORY_COSTS[t.type];return '<h2>What to measure after launch</h2><p>'+esc(d)+'</p><h2>Build the smallest working version first</h2><p>Write down the one customer journey that must work from start to finish. Confirm it in a separate test environment, record expected outcomes and keep a recovery path before enabling production traffic or payments. The following tutorials cover the individual tasks in more detail.</p>'+relatedHow(matchingHow(t.providers,t.type),'Follow the detailed how-to instructions')}

const BUDGET_CSV='Item,Billing period,Example USD,Monthly equivalent USD,Your monthly estimate USD,Verification notes\r\nHosting,Monthly,5,5,,Check commercial eligibility and overage rates\r\nDomain,Annual,15,1.25,,Confirm actual renewal quote\r\nDatabase,Monthly,0,0,,Confirm free allowance and write costs\r\nEmail,Monthly,0,0,,Confirm sending and daily limits\r\nAnalytics,Monthly,0,0,,Confirm pageview and website limits\r\nMonitoring,Monthly,0,0,,Confirm monitor limits\r\nOther services,Monthly,0,0,,Include backup and storage fees\r\nUsage overages,Monthly,0,0,,Estimate billable units after included allowance\r\nReserve,Monthly,1.25,1.25,,Example reserve of 20 percent\r\nIllustrative total,Monthly,7.50,7.50,,Sum your own estimates and verify current prices\r\n';
function worksheet(){return page('Free website budget worksheet and startup cost template | Project Zero','Download a free CSV website budget worksheet with monthly and annual cost examples, hosting, domains, database, email and usage charges.','/tools/website-budget-worksheet','<article class="detail"><div class="kicker">Free downloadable resource</div><h1>Website startup cost worksheet</h1><p class="lead">Build your own operating budget before committing to a hosting plan. Download the editable CSV and replace the example values with provider quotes.</p><div class="buttons"><a class="button" href="/downloads/website-budget-worksheet.csv" download>Download CSV worksheet ↓</a><a class="button secondary" href="/tools/hosting-cost-calculator">Use the interactive calculator →</a></div><p class="muted">No registration, email address or payment required. The worksheet contains illustrative assumptions, not current provider quotes.</p><h2>Worked monthly budget examples</h2><div class="cols"><div class="panel"><h3>Simple static website</h3><p>Hosting $0 + annual domain $15 ÷ 12 = <strong>$1.25/month</strong>, or $15/year. Only valid if the chosen free hosting plan permits your use and you stay within its allowances.</p></div><div class="panel"><h3>Small web application</h3><p>Hosting $5 + annual domain $15 ÷ 12 = $6.25/month. Add a 20% reserve of $1.25: <strong>$7.50/month</strong>, or $90/year. Database, email and other services are assumed to fit verified free allowances.</p></div></div><h2>What to record before choosing a plan</h2><ol class="checklist"><li>Record each recurring monthly charge and convert annual renewals into monthly equivalents. Keep one-time launch fees separate.</li><li>Estimate billable usage after included allowances: requests, CPU, storage, transfer, email and database writes.</li><li>Check minimum billing periods, commercial-use terms, taxes, cancellation and renewal costs.</li><li>Compare your total against your spending ceiling. Set actual provider-side budget limits and alerts where available; a worksheet does not prevent charges.</li><li>Record the quote date and a link to the official source. Recheck before purchasing or expanding usage.</li></ol><h2>Use and share this resource</h2><p>You may reuse and adapt this worksheet for your own planning or share a link to this page. Attribution is appreciated, not required. Use your own estimates and verify rates independently.</p><p><a href="/setups/launch-a-business-website">Website launch checklist</a> · <a href="/setups/build-a-low-cost-saas">Low-cost SaaS setup</a> · <a href="/compare/cloudflare-vs-digitalocean-vs-render">Hosting comparison</a></p></article>',[{name:'Calculators',path:'/tools'},{name:'Website budget worksheet',path:'/tools/website-budget-worksheet'}])}
function workedCosts(hosting){return hosting?'<h2>Worked example: a $10 monthly budget</h2><div class="panel"><p>$5 hosting + $15 annual domain ÷ 12 = $6.25/month. A 20% reserve adds $1.25, for <strong>$7.50/month</strong> and $2.50 remaining. If usage rises by $4 before reserve, the monthly total becomes $12.30, or $2.30 over budget. The reserve is planning headroom, not a provider spending limit.</p><a href="/tools/website-budget-worksheet">Download the editable budget worksheet →</a></div>':'<h2>Worked example: small versus larger transactions</h2><div class="cols"><div class="panel"><h3>100 sales at $9</h3><p>Gross $900. Model A (2.9% + $0.30) costs $56.10; model B (5% + $0.50) costs $95.00. Difference $38.90.</p></div><div class="panel"><h3>100 sales at $49</h3><p>Gross $4,900. Model A costs $172.10; model B costs $295.00. Difference $122.90.</p></div></div><p class="muted">Illustrative fee structures only. A processor and merchant of record may provide different tax, compliance and dispute services; the lowest fee is not automatically the best fit. Verify current contract terms.</p>'}
function relatedPlanning(p){const relevant={hosting:['/tools/hosting-cost-calculator','Estimate your monthly hosting costs'],domains:['/tools/website-budget-worksheet','Plan domain renewal and hosting costs'],database:['/tools/website-budget-worksheet','Estimate database and operating costs'],storage:['/tools/hosting-cost-calculator','Model storage-related usage costs'],payments:['/tools/payment-fee-calculator','Compare payment fees at your price'],commerce:['/setups/start-an-online-store','Plan store costs and per-order margins'],distribution:['/setups/release-a-desktop-app','Review software launch requirements'],analytics:['/setups/launch-a-business-website','Review the website launch and analytics checklist']};const r=relevant[p.category];return r?'<div class="panel"><h2>Plan your own costs</h2><p><a href="'+r[0]+'">'+esc(r[1])+' →</a></p></div>':''}

function resourceCards(){return '<div class="grid resource-grid"><a class="card" href="/tools/hosting-cost-calculator"><span class="mark">'+icon('hosting')+'</span><h3>Hosting cost calculator</h3><p>Estimate your monthly stack, usage and budget.</p></a><a class="card" href="/tools/payment-fee-calculator"><span class="mark">'+icon('payments')+'</span><h3>Payment fee calculator</h3><p>Compare two fee models at your actual sale price.</p></a><a class="card" href="/setups"><span class="mark">'+icon('ci')+'</span><h3>Project setup tutorials</h3><p>Practical launch checklists and example budgets.</p></a><a class="card" href="/tools/website-budget-worksheet"><span class="mark">'+icon('hosting')+'</span><h3>Website budget worksheet</h3><p>Free editable CSV with example costs and verification notes.</p></a></div>'}
function field(name,label,value,max=1000000,step='0.01'){return '<label class="calc-field">'+esc(label)+'<input name="'+name+'" type="number" inputmode="decimal" min="0" max="'+max+'" step="'+step+'" value="'+value+'"></label>'}
function result(key,label,value){return '<div><span>'+esc(label)+'</span><strong data-result="'+key+'">'+esc(value)+'</strong></div>'}
function calculator(path){if(path==='/tools/website-budget-worksheet')return worksheet();const hosting=path==='/tools/hosting-cost-calculator';if(!hosting&&path!=='/tools/payment-fee-calculator')return null;const name=hosting?'Hosting cost calculator':'Payment fee calculator',desc=hosting?'Estimate recurring hosting, domain, database and usage costs against a monthly budget.':'Compare payment fees and proceeds for two editable fee structures.';const inputs=hosting?'<div class="calc-inputs">'+field('hosting','Hosting / month ($)',5)+field('domain','Domain / year ($)',15)+field('database','Database / month ($)',0)+field('email','Email / month ($)',0)+field('analytics','Analytics / month ($)',0)+field('other','Other fixed costs / month ($)',0)+field('usage','Billable units / month',0,1e9,'1')+field('rate','Cost per billable unit ($)',0,1000000,'0.000001')+field('reserve','Reserve (%)',20,1000)+field('budget','Monthly budget ($)',10)+'</div>':'<div class="calc-inputs">'+field('price','Sale price ($)',19)+field('count','Sales per month',100,1e9,'1')+'</div><div class="calc-split"><div><h3>Fee model A</h3>'+field('percent_a','Percentage fee (%)',2.9,100)+field('fixed_a','Fixed fee per sale ($)',0.30)+field('monthly_a','Monthly fees ($)',0)+'</div><div><h3>Fee model B</h3>'+field('percent_b','Percentage fee (%)',5,100)+field('fixed_b','Fixed fee per sale ($)',0.50)+field('monthly_b','Monthly fees ($)',0)+'</div></div>';const results=hosting?result('total','Estimated monthly total','$7.50')+result('annual','Annual equivalent','$90.00')+result('fixed','Fixed monthly costs','$6.25')+result('variable','Metered usage','$0.00')+result('budget','Budget difference','$2.50 remaining'):result('gross','Gross sales','$1,900.00')+result('difference','Fee difference','$59.90 lower with A')+result('fee_a','Model A total fees','$85.10')+result('net_a','Model A proceeds','$1,814.90')+result('fee_b','Model B total fees','$145.00')+result('net_b','Model B proceeds','$1,755.00');const body='<article class="detail"><div class="kicker">Free interactive calculator</div><h1>'+name+'</h1><p class="lead">'+desc+'</p><div data-calculator="'+(hosting?'hosting':'payment')+'" class="calc-shell"><div class="calc-results" aria-live="polite">'+results+'</div><h2>Adjust your assumptions</h2>'+inputs+'<button class="button secondary" type="button" data-reset>Reset example</button><noscript><p>Enable JavaScript to recalculate. The default illustrative results appear above.</p></noscript></div><h2>How the estimate works</h2><p>'+(hosting?'Monthly total = (fixed monthly services + annual domain cost / 12 + billable units × unit rate) × (1 + reserve percentage / 100). Enter additional usage charges in other costs or combine them into your metered estimate. Free-tier allowances must be accounted for before entering billable units.':'Monthly fees = sales × (sale price × percentage fee / 100 + fixed per-sale fee) + monthly service fees. Proceeds = gross sales minus estimated fees. The example uses two editable fee models, not a live quote or a complete comparison of provider obligations.')+'</p><p class="notice">Illustrative USD estimates only. Include taxes, refunds, chargebacks, currency conversion, overages, subscriptions, plan restrictions and other costs separately as applicable. No inputs are submitted or saved by the calculator.</p>'+workedCosts(hosting)+'<h2>Compare actual providers</h2>'+compareCards(COMPARES.filter(c=>hosting?c.names.includes('Cloudflare'):c.names.includes('Stripe')))+'<p><a href="/setups">See example project setups →</a></p></article>';return page(name+' | Project Zero',desc,path,body,[{name:'Calculators',path:'/tools'},{name,path}])}
function setupPage(path,ps){if(path==='/setups')return page('Business project setup tutorials and budgets | Project Zero','Step-by-step setup tutorials for websites, SaaS, ecommerce, desktop apps, mobile apps and APIs.','/setups','<div class="hero"><div class="kicker">Practical launch plans</div><h1>Choose a project setup</h1><p class="lead">Start with the smallest stack your business needs. Each tutorial includes setup steps, budget examples and verification checks.</p></div><div class="grid">'+TUTORIALS.map(t=>'<a class="card" href="/setups/'+t.slug+'"><span class="mark">'+icon(t.type)+'</span><h3>'+esc(t.title)+'</h3><p>'+esc(t.desc)+'</p><small>Read setup →</small></a>').join('')+'</div>'+relatedHow(HOWTOS.slice(0,6),'Detailed how-to guides'),[{name:'Setups',path:'/setups'}]);const t=TUTORIALS.find(x=>path==='/setups/'+x.slug);if(!t)return null;return page(t.title+' — setup checklist and budget | Project Zero',t.desc,path,'<article class="detail"><div class="kicker">Project setup tutorial</div><h1>'+esc(t.title)+'</h1><p class="lead">'+esc(t.desc)+'</p><div class="pricing"><h2>Example budget</h2><p>'+esc(t.budget)+'</p><a class="button" href="/tools/hosting-cost-calculator">Estimate your costs →</a></div><p><a href="/tools/website-budget-worksheet">Download a free editable budget worksheet →</a></p><h2>Setup steps</h2><div class="tutorial-steps">'+t.steps.map(([name,desc],i)=>'<section class="panel"><h3>'+ (i+1)+'. '+esc(name)+'</h3><p>'+esc(desc)+'</p></section>').join('')+'</div><h2>Before going live</h2><ul class="checklist">'+t.tests.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'+setupEditorial(t)+'<p class="notice">These are illustrative plans, not preconfigured services or a guarantee of current provider prices. Verify official terms and costs, and obtain authorization before creating accounts, spending or deploying.</p></article><h2>Compare relevant platforms</h2><div class="grid">'+t.providers.map(n=>ps.find(p=>p.name===n)).filter(Boolean).map(card).join('')+'</div>',[{name:'Setups',path:'/setups'},{name:t.title,path}])}

function render(path,ps){if(path==='/how-to'||path.startsWith('/how-to/'))return howPage(path,ps);if(path==='/privacy')return page('Public website privacy | Project Zero','How optional analytics and public website data are handled.','/privacy',"<article class=\"detail\"><h1>Public website privacy</h1><p>These public pages can be used without an account. Hosting and security infrastructure may process network and request information to serve and protect the site.</p><h2>Optional analytics</h2><p>Analytics is disabled until you choose Allow analytics. SiteAPT, a related service under common ownership, measures public page paths, page titles, referrer domains, optional campaign tags, device and regional information, pseudonymous session identifiers, performance measurements, and named interaction events. It uses browser session storage for visitor/session identifiers and local storage to remember your choice. Calculator values, passwords and private project records are not sent by this website's analytics integration.</p><p>You can decline analytics or change your selection using Analytics preferences at the bottom of the page. Browser Do Not Track and Global Privacy Control are respected. Declining after allowing removes analytics session identifiers and reloads the page without the tracker. Previously received data is subject to SiteAPT's policies.</p><p><a href=\"https://siteapt.app/privacy\">SiteAPT privacy information</a></p><h2>External links</h2><p>Other websites have their own policies. Some public guides include disclosed affiliate links. Ordinary official pricing and provider links are also available. If you choose an affiliate link, the external provider and its affiliate platform may use cookies or other attribution methods under their own policies. The private workspace has separate access controls and is not included in public-site analytics.</p></article>",[{name:'Privacy',path:'/privacy'}]);if(path==='/tools')return page('Free business cost calculators | Project Zero','Estimate hosting and payment fees with adjustable inputs.','/tools','<div class="hero"><h1>Business cost calculators</h1><p class="lead">Model your expenses before committing to a platform.</p></div>'+resourceCards(),[{name:'Calculators',path:'/tools'}]);if(path.startsWith('/tools/'))return calculator(path);if(path==='/setups'||path.startsWith('/setups/'))return setupPage(path,ps);if(path==='/')return page('Compare business platforms, hosting and software tools | Project Zero','Independent guides to pricing, hosting, databases, payments, analytics and tools for building a business. Compare costs and choose a suitable stack.','/','<section class="hero"><div class="kicker">Build a business with the right tools</div><h1>Choose your business platforms with confidence.</h1><p class="lead">Compare hosting, payments, databases, analytics and other services by price, benefits and real operating costs. Start with your requirements and budget, not a list of subscriptions.</p><div class="buttons"><a class="button" href="/platforms">Explore '+ps.length+' platform guides →</a><a class="button secondary" href="/compare">Compare platforms</a><a class="button secondary" href="/how-to">Browse how-to guides</a></div><p class="muted">'+ps.filter(fresh).length+' pricing summaries checked in the past 30 days. Other guides clearly flag pending price reviews.</p></section><div class="sectionhead"><h2>Choose a category</h2></div>'+categoryCards(ps)+'<div class="sectionhead"><h2>Popular comparisons</h2><a href="/compare">All comparisons →</a></div>'+compareCards(COMPARES.slice(0,6))+relatedHow(HOWTOS.slice(0,8),'Popular how-to guides')+'<h2>Plan your own costs</h2>'+resourceCards()+'<h2>How to choose a low-cost stack</h2><div class="panel"><p>Start with a specific customer problem, a spending ceiling and a small first release. Reuse existing accounts. Check commercial-use restrictions on free plans, include renewal and usage fees, and set cost alerts before launch. Compare tools by what they actually do rather than their marketing labels.</p><a href="/methodology">How we review providers →</a></div>');
if(path==='/platforms')return page('Business platform directory: pricing, benefits and alternatives | Project Zero','Browse hosting, domains, databases, payments, email, analytics, AI tools and more. Compare pricing models, use cases and tradeoffs.','/platforms','<section class="hero"><div class="kicker">Platform directory</div><h1>Business platform pricing and guides</h1><p class="lead">Explore services by category and compare the cost of using them for your own project. Pricing is not a quote; follow the official sources before purchasing.</p></section>'+categoryCards(ps)+'<h2>All providers</h2>'+listing(ps),[{name:'Platforms',path:'/platforms'}],true,{'@type':'CollectionPage'});
if(path==='/compare')return page('Compare hosting, payment and software platforms | Project Zero','Side-by-side platform comparisons covering hosting, payments, databases, storage, email and ecommerce.','/compare','<section class="hero"><div class="kicker">Side-by-side comparisons</div><h1>Compare business platforms</h1><p class="lead">Find the right tool by understanding the real differences in architecture, pricing and responsibilities.</p></section>'+compareCards(COMPARES),[{name:'Compare',path:'/compare'}],true,{'@type':'CollectionPage'});
if(path==='/methodology')return page('Editorial policy, pricing methodology and disclosures | Project Zero','How Project Zero reviews business platforms, verifies prices, handles affiliate disclosures and compares services.','/methodology','<article class="detail"><h1>How we review platforms</h1><h2>Our approach</h2><p>These guides are editorial summaries of provider documentation and published pricing, designed to help founders make informed decisions. We do not claim hands-on tests or customer reviews unless specifically documented. We prioritize fit, commercial eligibility, total cost, security and operational requirements.</p><h2>Pricing updates</h2><p>Pricing summaries carry the date of their source review. Our target is a rolling monthly review; prices older than 30 days are marked for recheck. Guides remain readable and indexable when a price needs rechecking; historical pricing is clearly labeled. Setup advice is editorial guidance and not a claim of hands-on testing. We distinguish promotional, recurring, one-time, per-seat and usage-based costs. Official terms and checkout prices take precedence.</p><h2>Commercial relationships</h2><p>Project Zero participates in the Shopify affiliate program and may earn compensation from qualifying referrals. Compensated links on relevant public provider guides and how-to tutorials are identified and disclosed next to the link; ordinary links are also available. Compensation does not determine editorial rankings. SiteAPT is a related business under common ownership.</p><h2>Scope and privacy</h2><p>The public guides require no account and do not access private Project Zero projects, customer data or task records. The guides do not create accounts, purchase services or authorize deployment. The separate owner workspace remains protected.</p><h2>Corrections and source review</h2><p>Use the official pricing links on each guide to confirm current terms. A missing or stale review date means the price requires verification, not that the provider is unsuitable.</p><p><a href="/platforms">Explore the directory →</a></p></article>',[{name:'Editorial policy',path:'/methodology'}]);
if(path.startsWith('/categories/')){const k=path.slice(12),c=CATEGORIES[k];if(!c)return null;const list=ps.filter(p=>p.category===k);return page(c[0]+' — pricing and comparisons | Project Zero',c[1],path,'<section class="hero"><div class="row"><span class="mark">'+icon(k)+'</span><div class="kicker">Platform category</div></div><h1>'+esc(c[0])+'</h1><p class="lead">'+esc(c[1])+'</p><p>'+esc(c[2])+'</p></section><h2>Compare providers</h2>'+listing(list)+'<article class="panel"><h2>Before choosing a provider</h2>'+checklist(k)+'<h2>Estimate your true operating costs</h2><p>'+esc(CATEGORY_COSTS[k])+'</p></article>'+relatedHow(matchingHow(list.map(p=>p.name),k),'Learn how to use these tools')+''+ (COMPARES.some(x=>x.names.some(n=>list.some(p=>p.name===n)))?'<h2>Detailed comparisons</h2>'+compareCards(COMPARES.filter(x=>x.names.some(n=>list.some(p=>p.name===n)))):''),[{name:'Platforms',path:'/platforms'},{name:c[0],path}],true,{'@type':'CollectionPage'})}
if(path.startsWith('/platforms/')){const p=ps.find(x=>ppath(x)===path);if(!p)return null;const c=CATEGORIES[p.category],related=ps.filter(x=>x.category===p.category&&x.name!==p.name),comps=COMPARES.filter(x=>x.names.includes(p.name));const title=p.name+' pricing, benefits and alternatives | Project Zero';const desc='Compare '+p.name+' pricing, benefits, ideal use cases and limitations. '+p.best_for+' Review official costs and alternatives.';return page(title,desc.slice(0,175),path,'<article class="detail"><div class="row"><span class="mark">'+icon(p.category)+'</span><span class="kicker">'+esc(c[0])+'</span></div><h1>'+esc(p.name)+' pricing, benefits and alternatives</h1><p class="lead">'+esc(p.benefits)+'</p>'+pricing(p)+'<div class="cols"><section class="panel"><h2>Who is it for?</h2><p>'+esc(p.best_for)+'</p></section><section class="panel"><h2>Limitations and extra costs</h2><p>'+esc(p.tradeoffs)+'</p></section></div><h2>How to decide if '+esc(p.name)+' fits your project</h2><p>'+esc(c[2])+'</p>'+checklist(p.category)+editorial(p)+'<h2>Questions to answer before signing up</h2><details open><summary>Is the entry plan right for my business?</summary><p>'+esc(p.tradeoffs)+' Confirm that the provider allows your intended use and that its limits support your actual workload.</p></details><details><summary>What will I pay as the project grows?</summary><p>Use the official pricing source to estimate your own usage, then include any separate services, renewal charges and applicable taxes. Do not assume a starting price is a spending ceiling.</p></details><details><summary>What should I verify before going live?</summary><p>Test the service with a small nonproduction workload, check permissions and recovery, confirm billing alerts, and record a rollback plan.</p></details>'+relatedPlanning(p)+'<h2>Sources and disclosure</h2><p class="source">'+sourceLink(p)+' · '+esc(dateText(p))+'</p><p class="notice">'+esc(disclosure(p))+'</p><p class="muted">Editorial summary of provider information, not a claim of hands-on testing. <a href="/methodology">Review policy</a>.</p></article>'+(comps.length?'<h2>Compare '+esc(p.name)+' with alternatives</h2>'+compareCards(comps):'')+(related.length?'<h2>Other '+esc(c[0].toLowerCase())+' tools</h2><div class="grid">'+related.map(card).join('')+'</div>':''),[{name:'Platforms',path:'/platforms'},{name:c[0],path:cpath(p.category)},{name:p.name,path}],true,validDate(p.verified_at)?{dateModified:p.verified_at}:{})}
if(path.startsWith('/compare/')){const c=COMPARES.find(x=>'/compare/'+x.slug===path);if(!c)return null;const list=c.names.map(n=>ps.find(p=>p.name===n)).filter(Boolean);const related=COMPARES.filter(x=>x.slug!==c.slug&&x.names.some(n=>c.names.includes(n)));return page(c.title+' — pricing and differences | Project Zero',c.desc,path,'<article class="detail comparison-detail"><div class="kicker">Platform comparison</div><h1>'+esc(c.title)+'</h1><p class="lead">'+esc(c.desc)+'</p><h2 class="compare-section-title">Pricing &amp; key differences</h2>'+comparisonProviders(list)+'<div class="compare-decision"><h2>Which should you choose?</h2><p>'+esc(c.decision)+'</p></div>'+comparisonEditorial(c)+'<h2>Estimate your costs</h2>'+resourceCards()+'<h2>Decision checklist</h2><ul class="checklist">'+c.checks.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p class="notice">Select based on your requirements, budget, existing infrastructure and verified terms. Official pricing links in these comparisons are untracked. Any compensated link on a provider guide is identified and disclosed. <a href="/methodology">Editorial policy</a>.</p></article><div class="sectionhead"><h2>More platform comparisons</h2><a href="/compare">View all →</a></div>'+compareCards((related.length?related:COMPARES.filter(x=>x.slug!==c.slug)).slice(0,3)),[{name:'Compare',path:'/compare'},{name:c.title,path}])}
return null}
export default {async fetch(req,env,ctx){const u=new URL(req.url);if(u.hostname!==HOST)return res('Not found',404,'text/plain; charset=utf-8',false,'no-store');if(!['GET','HEAD'].includes(req.method))return res('Method not allowed',405,'text/plain; charset=utf-8',false,'no-store');let path=u.pathname;if(path==='/favicon.ico')return new Response(req.method==='HEAD'?null:Uint8Array.from(atob(PZ_KIT_ICO),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/x-icon','Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'}});if(path!=='/'&&path.endsWith('/'))return Response.redirect(BASE+path.replace(/\/+$/,''),301);if(u.search)return Response.redirect(BASE+path,301);if(['GET','HEAD'].includes(req.method)&&['/favicon.svg','/favicon-v2.svg','/logo.svg','/logo-dark.svg'].includes(path))return new Response(req.method==='HEAD'?null:(path==='/logo.svg'?PZ_BRAND_LIGHT:path==='/logo-dark.svg'?PZ_BRAND_DARK:PZ_BRAND_FAVICON),{headers:{'Content-Type':'image/svg+xml','Cache-Control':'public, max-age=300','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; sandbox"}});let r;if(path==='/assets/search-v1.js')r=res(FILTER,200,'application/javascript; charset=utf-8',false,'public, max-age=86400');else if((path==='/assets/analytics-v1.js'||path==='/assets/analytics-v2.js'))r=res(ANALYTICS_SCRIPT,200,'application/javascript; charset=utf-8',false,'public, max-age=86400');else if(path==='/assets/calculators-v1.js')r=res(CALCULATOR,200,'application/javascript; charset=utf-8',false,'public, max-age=86400');else if(path==='/downloads/website-budget-worksheet.csv')return new Response(req.method==='HEAD'?null:BUDGET_CSV,{headers:{...HEADERS,'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename="project-zero-website-budget-worksheet.csv"','Cache-Control':'public, max-age=3600','X-Robots-Tag':'noindex'}});else if(path==='/robots.txt')r=res('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n',200,'text/plain; charset=utf-8',true);else{const known=path==='/'||path==='/platforms'||path==='/compare'||path==='/methodology'||path==='/sitemap.xml'||path==='/privacy'||path==='/tools'||path==='/setups'||path==='/how-to'||/^\/(?:platforms|categories|compare|tools|setups|how-to)\/[a-z0-9-]{1,100}$/.test(path);if(!known)return res('Not found',404,'text/plain; charset=utf-8',false,'no-store');const key=new Request(BASE+path+'?cache=standard-footer-v10',{method:'GET'});try{r=await caches.default.match(key);if(!r){const ps=await load(env);r=path==='/sitemap.xml'?res(sitemap(ps),200,'application/xml; charset=utf-8'):render(path,ps);if(!r)r=res('Guide not found',404,'text/plain; charset=utf-8',false,'no-store');if(r.status===200)ctx.waitUntil(caches.default.put(key,r.clone()).catch(()=>{}))}}catch{return res('Guides temporarily unavailable. Please try again later.',503,'text/plain; charset=utf-8',false,'no-store')}}return req.method==='HEAD'?new Response(null,{status:r.status,headers:r.headers}):r}};
